import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = { blue: "#0066FF", record: "#315EFF", ink: "#17233B", slate: "#64748B", amber: "#E8AD36", amberInk: "#80540C", porcelain: "#F3F5F8", white: "#F8FAFC" };
const HEAD = '"Inter Tight", "Inter", sans-serif';
const TEXT = '"Inter", sans-serif';
const MONO = '"IBM Plex Mono", monospace';
const fallback = [10, 66, 77, 109, 121, 132, 147, 157, 163, 180, 186, 205, 214, 228, 238, 256, 309, 340, 364, 382, 397, 428];
const ease = Easing.bezier(0.22, 1, 0.36, 1);
const fluid = Easing.bezier(0.45, 0, 0.2, 1);
const coloredShadow = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.09)";

const BallotSilhouette: React.FC = () => (
  <svg width={360} height={340} viewBox="0 0 360 340" fill="none" aria-label="Ballot box with a ballot slip" style={{ overflow: "visible" }}>
    <defs>
      <linearGradient id="s01Body" x1="73" y1="112" x2="270" y2="315" gradientUnits="userSpaceOnUse">
        <stop stopColor="#FFFFFF" /><stop offset="0.57" stopColor="#ECF3FF" /><stop offset="1" stopColor="#B4CCF5" />
      </linearGradient>
      <linearGradient id="s01Lid" x1="51" y1="97" x2="310" y2="145" gradientUnits="userSpaceOnUse">
        <stop stopColor="#FFFFFF" /><stop offset="1" stopColor="#CEDFFF" />
      </linearGradient>
      <linearGradient id="s01Face" x1="94" y1="163" x2="246" y2="281" gradientUnits="userSpaceOnUse">
        <stop stopColor="#F9FCFF" stopOpacity="0.96" /><stop offset="1" stopColor="#ADC6F1" stopOpacity="0.66" />
      </linearGradient>
      <filter id="s01Ground" x="-50%" y="-100%" width="200%" height="300%"><feGaussianBlur stdDeviation="8" /></filter>
    </defs>
    <ellipse cx="181" cy="322" rx="130" ry="9" fill="#0066FF" opacity="0.32" filter="url(#s01Ground)" />
    <rect x="65" y="120" width="230" height="185" rx={24} ry={24} fill="url(#s01Body)" stroke="#DCE9FF" strokeWidth="1.5" />
    <rect x="49" y="94" width="262" height="53" rx={22} ry={22} fill="url(#s01Lid)" stroke="#FFFFFF" strokeWidth="1.5" />
    <rect x="109" y="104" width="142" height="24" rx={20} ry={20} fill="#233955" />
    <rect x="88" y="163" width="163" height="116" rx={24} ry={24} fill="url(#s01Face)" stroke="#FFFFFF" strokeOpacity="0.82" strokeWidth="1.5" />
    <rect x="140" y="24" width="83" height="98" rx={20} ry={20} transform="rotate(-10 181.5 73)" fill="#FFFFFF" stroke="#C1D7FF" strokeWidth="2" />
    <path d="M164  seventy" visibility="hidden" />
    <path d="M164 72 L195 66" stroke="#0066FF" strokeWidth="8" strokeLinecap="round" />
    <path d="M274 163 V267 Q274 283 261 289" stroke="#7192C8" strokeOpacity="0.65" strokeWidth="3" strokeLinecap="round" />
  </svg>
);

const RecordToken: React.FC = () => (
  <div style={{ width: 138, height: 76, borderRadius: 24, boxSizing: "border-box", background: C.record, border: "1px solid rgba(255,255,255,0.34)", boxShadow: "0 20px 60px rgba(0,102,255,0.25)", position: "relative", display: "flex", alignItems: "center", justifyContent: "center", color: "#FFFFFF" }}>
    <div style={{ position: "absolute", top: 13, left: 55, width: 28, height: 4, borderRadius: 9999, background: "#FFFFFF", opacity: 0.93 }} />
    <span style={{ marginTop: 14, fontFamily: MONO, fontWeight: 500, fontSize: 24, lineHeight: 1, letterSpacing: "0.025em", fontVariantNumeric: "tabular-nums" }}>R-001</span>
  </div>
);

export const GeneratedShot: React.FC<ShotProps> = (props) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const at = (index: number) => {
    const explicit = cues.find((c) => c.wordIndex === index || c.index === index);
    return explicit?.startFrame ?? cues[index]?.startFrame ?? fallback[index];
  };
  const tween = (a: number, b: number, from = 0, to = 1, easing = ease) => interpolate(frame, [a, Math.max(a + 1, b)], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing });
  const snap = (start: number) => spring({ frame: Math.max(0, frame - start), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const firstPushEnd = at(2) + 36;
  const trackStart = at(16);
  const trackEnd = at(19) + 14;
  const pullStart = at(20);
  const pullEnd = at(21) + 28;
  const ambientStart = pullEnd + 1;
  const lastFrame = Math.max(ambientStart + 1, durationInFrames - 1);
  let zoom = 1.15;
  let panX = 0;
  let panY = -30;
  if (frame <= firstPushEnd) {
    zoom = tween(0, firstPushEnd, 1.15, 1.18, fluid);
    panX = tween(0, firstPushEnd, 0, -20, fluid);
    panY = tween(0, firstPushEnd, -30, -40, fluid);
  } else if (frame < trackStart) {
    zoom = 1.18; panX = -20; panY = -40;
  } else if (frame <= trackEnd) {
    zoom = tween(trackStart, trackEnd, 1.18, 1.12, fluid);
    panX = tween(trackStart, trackEnd, -20, 25, fluid);
    panY = tween(trackStart, trackEnd, -40, -30, fluid);
  } else if (frame < pullStart) {
    zoom = 1.12; panX = 25; panY = -30;
  } else if (frame <= pullEnd) {
    zoom = tween(pullStart, pullEnd, 1.12, 1, fluid);
    panX = tween(pullStart, pullEnd, 25, 0, fluid);
    panY = tween(pullStart, pullEnd, -30, 0, fluid);
  } else {
    zoom = tween(ambientStart, lastFrame, 1, 1.015, fluid);
  }
  const queueOff = 1 - tween(at(10) + 4, at(10) + 22);
  const queueLine = 1 - tween(at(5), at(10) + 8);
  const ballotOpen = tween(at(0), at(0) + 28);
  const ballotRemove = tween(at(14), at(15) + 31, 0, 1, fluid);
  const ballotFade = 1 - tween(at(15) + 10, at(15) + 31);
  const ballotFold = tween(at(15), at(15) + 30, 0, 1, fluid);
  const railBright = tween(at(16), at(17) + 20);
  const fanOpen = tween(pullStart, pullEnd);
  const move = tween(at(18), trackEnd, 0, 1, fluid);
  const tokenX = 916 - 292 * move;
  const tokenY = 493 + 122 * move - Math.sin(move * Math.PI) * 43;
  const tokenReveal = Math.min(1, snap(at(16)));
  const tokenOpacity = tween(at(16), at(16) + 12);
  const tokenTilt = -5 * (1 - move);
  const settled = frame >= trackEnd;
  const qualifier = Math.min(1.025, snap(pullStart));
  const qualifierOpacity = tween(pullStart, pullStart + 12);
  const storedLabel = tween(at(21), at(21) + 22);
  const ambient = Math.sin(frame / 110) * 0.015;
  const railCenters = [693, 981, 1269];
  const slots = [591, 879, 1167];
  const railShadow = `0 20px 60px rgba(0,102,255,${0.10 + railBright * 0.10}), 0 8px 24px rgba(0,0,0,0.045)`;

  return (
    <AbsoluteFill style={{ background: C.porcelain, overflow: "hidden" }}>
      <div style={{ width: 1920, height: 1080, position: "absolute", left: 0, top: 0, transform: `scale(${width / 1920}, ${height / 1080})`, transformOrigin: "0 0", fontFamily: TEXT, color: C.ink, WebkitFontSmoothing: "antialiased" }}>
        <AbsoluteFill style={{ background: "linear-gradient(155deg, #F9FBFF 0%, #EDF2FA 36%, #E4EBF7 69%, #F6F8FB 100%)" }} />
        <AbsoluteFill style={{ opacity: 0.36 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ background: `radial-gradient(ellipse 58% 67% at ${66 + frame / 200}% 30%, rgba(0,102,255,${0.13 + ambient}), transparent 73%), radial-gradient(ellipse 40% 42% at 17% 74%, rgba(232,173,54,0.10), transparent 72%)` }} />

        <div style={{ position: "absolute", left: 115, top: 150, width: 1690, height: 850, borderRadius: 28, boxSizing: "border-box", overflow: "hidden", background: "rgba(255,255,255,0.76)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.85)", boxShadow: "0 20px 60px rgba(0,102,255,0.25)" }}>
          <AbsoluteFill style={{ opacity: 0.23 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
          <AbsoluteFill style={{ background: "radial-gradient(ellipse 65% 65% at 57% 42%, rgba(255,255,255,0.98), rgba(255,255,255,0.12) 67%), radial-gradient(ellipse 42% 60% at 92% 12%, rgba(0,102,255,0.09), transparent 76%)" }} />
          <div style={{ position: "absolute", top: 72, bottom: 58, left: 39, width: 1, borderRadius: 9999, background: "linear-gradient(transparent, rgba(0,102,255,0.12), transparent)" }} />
          <div style={{ position: "absolute", top: 72, bottom: 58, right: 39, width: 1, borderRadius: 9999, background: "linear-gradient(transparent, rgba(0,102,255,0.12), transparent)" }} />
          <div style={{ position: "absolute", left: 76, right: 76, bottom: 47, height: 1, borderRadius: 9999, background: "linear-gradient(90deg, transparent, rgba(0,102,255,0.12), rgba(232,173,54,0.17), transparent)" }} />
          <mg.Marker x={44} y={93} variant="cross" color="#0066FF" />
          <mg.Marker x={1642} y={93} variant="cross" color="#0066FF" />
          <mg.Marker x={1642} y={791} variant="cross" color="#E8AD36" />
        </div>

        <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
          <mg.CameraRig zoom={Math.min(1.18, zoom)} x={panX} y={panY}>
            <div style={{ position: "absolute", width: 1920, height: 1080, left: 0, top: 0, overflow: "visible", perspective: 1100, perspectiveOrigin: "960px 540px" }}>
              <svg width={1920} height={1080} viewBox="0 0 1920 1080" style={{ position: "absolute", inset: 0, overflow: "visible" }} fill="none">
                <defs>
                  <filter id="mgGlow" x="-80%" y="-250%" width="260%" height="600%"><feGaussianBlur stdDeviation="3" /></filter>
                  <filter id="mgSoft" x="-80%" y="-250%" width="260%" height="600%"><feGaussianBlur stdDeviation="8" /></filter>
                  <linearGradient id="s01Transfer" x1="985" y1="537" x2="693" y2="653" gradientUnits="userSpaceOnUse"><stop stopColor="#0066FF" stopOpacity="0.10" /><stop offset="1" stopColor="#0066FF" stopOpacity="0.5" /></linearGradient>
                </defs>
                <path d="M723 488 C753 488 750 488 780 488" stroke="#0066FF" strokeWidth="2" strokeDasharray="3 7" strokeLinecap="round" opacity={0.32 * queueLine} />
                <path d="M985 537 C985 567 747 562 693 653" stroke="url(#s01Transfer)" strokeWidth="2" strokeDasharray="4 8" strokeLinecap="round" opacity={tokenOpacity * (1 - tween(pullStart, pullStart + 22)) * 0.7} />
                <path d="M985 537 C985 567 747 562 693 653" pathLength={1} stroke="#0066FF" strokeWidth="7" strokeDasharray={`${0.065 * tokenOpacity} 1`} strokeDashoffset={-move * 0.91} opacity={tokenOpacity * (1 - tween(trackEnd - 6, trackEnd + 9)) * 0.35} filter="url(#mgSoft)" />
              </svg>

              <div style={{ position: "absolute", left: 560, top: 590, width: 834, height: 104, borderRadius: 24, background: "rgba(225,235,255,0.48)", border: "1px solid rgba(0,102,255,0.10)", boxShadow: coloredShadow, transform: `translate(${16 * fanOpen}px, ${16 * fanOpen}px)`, opacity: 0.34 * fanOpen }} />
              <div style={{ position: "absolute", left: 560, top: 590, width: 842, height: 112, borderRadius: 24, boxSizing: "border-box", background: "rgba(238,244,255,0.64)", border: "1px solid rgba(0,102,255,0.11)", boxShadow: "0 12px 30px rgba(0,102,255,0.09)", transform: `translate(${8 * fanOpen}px, ${8 * fanOpen}px)`, opacity: 0.64 * fanOpen }} />
              <div style={{ position: "absolute", left: 560, top: 590, width: 850, height: 120, borderRadius: 24, boxSizing: "border-box", background: `rgba(255,255,255,${0.62 + railBright * 0.22})`, backdropFilter: "blur(14px)", border: `1px solid rgba(0,102,255,${0.10 + railBright * 0.10})`, boxShadow: railShadow }}>
                <div style={{ position: "absolute", left: 28, top: 8, fontFamily: MONO, fontWeight: 500, fontSize: 12, lineHeight: "16px", letterSpacing: "0.12em", color: C.slate }}>ILLUSTRATIVE RECORD SLOTS</div>
              </div>
              <svg width={850} height={120} viewBox="0 0 850 120" style={{ position: "absolute", left: 560, top: 590, overflow: "visible" }} fill="none">
                {[0, 1].map((i) => {
                  const start = i === 0 ? at(17) : at(18);
                  const reveal = tween(start, start + 24);
                  const x = 235 + i * 288;
                  return <g key={i}>
                    <path d={`M${x} 63 H${x + 84}`} stroke="#0066FF" strokeWidth="7" opacity={0.13 * reveal} pathLength={1} strokeDasharray="1" strokeDashoffset={1 - reveal} strokeLinecap="round" filter="url(#mgSoft)" />
                    <path d={`M${x} 63 H${x + 84}`} stroke="#0066FF" strokeWidth="2" opacity={0.35 + 0.3 * reveal} pathLength={1} strokeDasharray="1" strokeDashoffset={1 - reveal} strokeLinecap="round" />
                    <circle cx={x + 42} cy={63} r={3} fill="#0066FF" opacity={0.58 * reveal} />
                  </g>;
                })}
              </svg>
              {slots.map((left, i) => (
                <div key={i} style={{ position: "absolute", left, top: 605, width: 204, height: 96, boxSizing: "border-box", borderRadius: 24, background: i === 0 && settled ? "rgba(49,94,255,0.075)" : "linear-gradient(150deg, rgba(240,246,255,0.9), rgba(255,255,255,0.85))", border: `1px solid rgba(0,102,255,${0.10 + railBright * (i === 0 ? 0.17 : 0.07)})`, boxShadow: "inset 0 2px 8px rgba(0,102,255,0.035), 0 5px 16px rgba(0,102,255,0.04)", opacity: 0.56 + railBright * 0.44 }}>
                  <div style={{ position: "absolute", top: 15, left: 11, fontFamily: MONO, fontSize: 11, lineHeight: "14px", fontWeight: 500, fontVariantNumeric: "tabular-nums", color: C.slate }}>{String(i + 1).padStart(2, "0")}</div>
                  {(i > 0 || !settled) && <div style={{ position: "absolute", left: 87, top: 45, width: 30, height: 4, borderRadius: 9999, background: "rgba(0,102,255,0.16)", opacity: i === 0 ? 1 - move : 1 }} />}
                </div>
              ))}

              <div style={{ position: "absolute", left: 420, top: 416, width: 310, height: 120, borderRadius: 24, overflow: "hidden", opacity: queueOff }}>
                <div style={{ position: "absolute", left: 10, top: 0, fontSize: 17, lineHeight: "22px", letterSpacing: "0.16em", fontWeight: 600, color: C.slate }}>QUEUE</div>
                {[0, 1, 2, 3].map((i) => {
                  const delay = at(5) + (3 - i) * 5;
                  const retract = tween(delay, delay + 45, 0, 1, fluid);
                  const entrance = Math.min(1.025, snap(at(0) + i * 5));
                  return (
                    <div key={i} style={{ position: "absolute", left: 7 + i * 65 - 344 * retract, top: 28, width: 92, height: 78, boxSizing: "border-box", borderRadius: 24, background: "linear-gradient(145deg, #FFFFFF 0%, #EFF5FF 100%)", border: "2px solid rgba(0,102,255,0.72)", boxShadow: "0 8px 22px rgba(0,102,255,0.15)", opacity: tween(at(0) + i * 5, at(0) + i * 5 + 12), transform: `translateY(${(1 - entrance) * 16}px)`, zIndex: i }}>
                      <div style={{ position: "absolute", left: 19, top: 24, width: 35, height: 5, borderRadius: 9999, background: C.blue, opacity: 0.64 }} />
                      <div style={{ position: "absolute", left: 19, top: 39, width: 21, height: 4, borderRadius: 9999, background: C.blue, opacity: 0.20 }} />
                    </div>
                  );
                })}
                <div style={{ position: "absolute", left: 0, top: 25, width: 32, height: 86, borderRadius: 24, background: "linear-gradient(90deg, #F8FAFE 0%, rgba(248,250,254,0) 100%)", opacity: tween(at(5), at(5) + 10), zIndex: 10 }} />
              </div>

              {ballotFade > 0 && <div style={{ position: "absolute", left: 780, top: 320, width: 360, height: 340, borderRadius: 24, transformOrigin: "50% 96%", opacity: ballotFade, transform: `translateY(${-16 * ballotRemove + 8 * (1 - ballotOpen)}px) rotateX(${68 * ballotFold}deg) rotateZ(${-3 * ballotRemove}deg) scale(${1 - ballotRemove * 0.09})` }}>
                <div style={{ position: "absolute", left: 0, top: 0, width: 360, height: 324, borderRadius: 24, boxSizing: "border-box", background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxShadow: "0 20px 60px rgba(0,102,255,0.30), 0 8px 24px rgba(0,0,0,0.20)", overflow: "hidden" }}>
                  <AbsoluteFill style={{ background: "radial-gradient(ellipse 100% 85% at 20% 0%, rgba(0,102,255,0.26), transparent 70%), linear-gradient(140deg, rgba(255,255,255,0.06), transparent 57%)" }} />
                  <div style={{ position: "absolute", top: -130, bottom: -130, left: -280 + ballotRemove * 830, width: 145, borderRadius: 28, transform: "rotate(25deg)", background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.18), transparent)", opacity: ballotRemove }} />
                </div>
                <BallotSilhouette />
              </div>}

              <div style={{ position: "absolute", left: 565, top: 547, width: 256, height: 34, boxSizing: "border-box", borderRadius: 9999, display: "flex", alignItems: "center", justifyContent: "center", gap: 10, background: "rgba(255,247,227,0.95)", border: "1px solid rgba(232,173,54,0.55)", boxShadow: "0 8px 25px rgba(232,173,54,0.18)", opacity: qualifierOpacity, transform: `translateY(${(1 - qualifier) * 12}px) scale(${0.97 + qualifier * 0.03})` }}>
                <div style={{ width: 7, height: 7, flexShrink: 0, borderRadius: 9999, background: C.amber }} />
                <span style={{ fontSize: 15, lineHeight: "18px", fontWeight: 600, letterSpacing: "0.085em", color: C.amberInk }}>IMAGINED PROMISE</span>
              </div>
              <div style={{ position: "absolute", left: 588, top: 602, width: 210, height: 102, borderRadius: 24, opacity: qualifierOpacity, transform: `scale(${0.95 + qualifier * 0.05})`, boxShadow: `0 0 ${18 + qualifierOpacity * 8}px rgba(232,173,54,${qualifierOpacity * 0.14})` }}>
                <mg.FocusFrame color="#E8AD36" borderRadius={24} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", borderRadius: 24 }}>
                  <div style={{ width: 210, height: 102, borderRadius: 24, boxSizing: "border-box", border: "1px solid rgba(232,173,54,0.40)" }} />
                </mg.FocusFrame>
              </div>

              <div style={{ position: "absolute", left: tokenX, top: tokenY, width: 138, height: 76, borderRadius: 24, opacity: tokenOpacity, transformOrigin: "50% 50%", transform: `translateY(${(1 - tokenReveal) * 18}px) rotate(${tokenTilt}deg)` }}>
                <RecordToken />
              </div>
              <div style={{ position: "absolute", left: railCenters[0] - 153, top: 735, width: 306, textAlign: "center", opacity: storedLabel, transform: `translateY(${(1 - storedLabel) * 8}px)` }}>
                <div style={{ width: 1, height: 14, borderRadius: 9999, background: "rgba(49,94,255,0.33)", position: "absolute", left: 152, top: -21 }} />
                <div style={{ fontFamily: TEXT, fontSize: 18, fontWeight: 500, lineHeight: "26px", letterSpacing: "0.075em", color: C.ink, whiteSpace: "nowrap" }}>STORED VOTE RECORD</div>
              </div>
            </div>
          </mg.CameraRig>
        </div>

        <div style={{ position: "absolute", left: 120, top: 82, fontFamily: TEXT, fontSize: 23, lineHeight: "28px", fontWeight: 500, letterSpacing: "0.14em", color: C.blue }}>THE PROMISE</div>
        <div style={{ position: "absolute", left: 120, top: 116, fontFamily: HEAD, fontSize: 54, fontWeight: 600, letterSpacing: "-0.04em", lineHeight: "64px", color: C.ink, whiteSpace: "nowrap" }}>The frictionless election</div>
        <div style={{ position: "absolute", left: 1515, top: 91, width: 280, display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 12, fontFamily: MONO, fontSize: 12, fontWeight: 500, lineHeight: "20px", letterSpacing: "0.08em", color: C.slate }}>
          <div style={{ width: 7, height: 7, borderRadius: 9999, background: C.amber }} />
          <span>CONCEPTUAL SEQUENCE / 01</span>
        </div>
        <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "multiply" }}><mg.Noise opacity={0.035} /></AbsoluteFill>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[]; recordId?: string; inheritedRecordId?: string };

const C = { blue: '#0066FF', record: '#315EFF', emerald: '#00A77B', coral: '#FF5A36', softCoral: '#F36B59', amber: '#E8AD36', ink: '#17233B', slate: '#64748B', white: '#F8FAFC' };
const sans = 'Inter, Arial, sans-serif';
const tight = 'Inter Tight, Inter, Arial, sans-serif';
const mono = 'IBM Plex Mono, SFMono-Regular, Consolas, monospace';
const clampOptions = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const ease = Easing.bezier(0.22, 0.76, 0.25, 1);

const NODES = [
  { label: 'COPY A', x: 510, y: 400 },
  { label: 'COPY B', x: 960, y: 400 },
  { label: 'COPY C', x: 1410, y: 400 },
  { label: 'COPY D', x: 510, y: 700 },
  { label: 'COPY E', x: 960, y: 700 },
  { label: 'COPY F', x: 1410, y: 700 },
];

type Point = [number, number];
type Link = { a: Point; b: Point; c: Point; d: Point; delay: number; reverse?: boolean };
const LINKS: Link[] = [
  { a: [660, 400], b: [718, 355], c: [752, 355], d: [810, 400], delay: 0, reverse: true },
  { a: [1110, 400], b: [1165, 355], c: [1205, 355], d: [1260, 400], delay: 4 },
  { a: [660, 700], b: [718, 745], c: [752, 745], d: [810, 700], delay: 8 },
  { a: [1110, 700], b: [1165, 745], c: [1205, 745], d: [1260, 700], delay: 12, reverse: true },
  { a: [510, 487], b: [476, 529], c: [476, 571], d: [510, 613], delay: 6 },
  { a: [960, 487], b: [986, 529], c: [986, 571], d: [960, 613], delay: 10 },
  { a: [1410, 487], b: [1444, 529], c: [1444, 571], d: [1410, 613], delay: 14, reverse: true },
  { a: [660, 459], b: [724, 493], c: [746, 584], d: [810, 639], delay: 18 },
  { a: [1110, 639], b: [1170, 591], c: [1200, 496], d: [1260, 459], delay: 22, reverse: true },
];
const pathFor = (l: Link) => 'M ' + l.a.join(' ') + ' C ' + l.b.join(' ') + ' ' + l.c.join(' ') + ' ' + l.d.join(' ');
const pointOn = (l: Link, t: number): Point => {
  const u = 1 - t;
  return [u * u * u * l.a[0] + 3 * u * u * t * l.b[0] + 3 * u * t * t * l.c[0] + t * t * t * l.d[0], u * u * u * l.a[1] + 3 * u * u * t * l.b[1] + 3 * u * t * t * l.c[1] + t * t * t * l.d[1]];
};

const Check = ({ color, size = 18 }: { color: string; size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <circle cx="12" cy="12" r="9" stroke={color} strokeWidth="1.6" opacity="0.5" />
    <path d="M7.5 12.2 10.5 15.2 16.7 8.8" stroke={color} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const Alert = ({ color, size = 18 }: { color: string; size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <circle cx="12" cy="12" r="9" stroke={color} strokeWidth="1.8" />
    <path d="M12 6.8v6.5" stroke={color} strokeWidth="2.4" strokeLinecap="round" />
    <circle cx="12" cy="17" r="1.2" fill={color} />
  </svg>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number, word: string, end = false) => {
    const normalize = (s: string) => s.toLowerCase().replace(/[^a-z]/g, '');
    const byIndex = cues.find(c => (c.wordIndex ?? c.index) === index);
    const byWord = cues.find(c => normalize(c.word ?? c.text ?? '') === normalize(word));
    const value = end ? (byIndex ?? byWord)?.endFrame : (byIndex ?? byWord)?.startFrame;
    return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value < durationInFrames ? value : fallback;
  };
  const perfectAt = cueAt(23, 13, 'perfect');
  const rightEnd = cueAt(24, 48, 'right', true);
  const inspectionAt = cueAt(25, 95, "It's");
  const transparentAt = cueAt(26, 107, 'transparent');
  const transparentEnd = cueAt(26, 152, 'transparent', true);
  const trackingAt = cueAt(27, 179, "it's");
  const decentralizedAt = cueAt(28, 202, 'decentralized');
  const decentralizedEnd = cueAt(28, 258, 'decentralized', true);
  const nobodyAt = cueAt(29, 277, 'Nobody');
  const secretlyAt = cueAt(31, 323, 'secretly');
  const changeAt = cueAt(32, 352, 'change');
  const votesEnd = cueAt(34, 406, 'votes', true);
  const soAt = cueAt(35, 451, 'So');
  const whyAt = cueAt(36, 458, 'why');
  const electionsAt = cueAt(41, 504, 'elections');
  const blockchainAt = cueAt(43, 547, 'blockchain');
  const questionEnd = cueAt(43, 578, 'blockchain', true);
  const tween = (a: number, b: number, from = 0, to = 1) => interpolate(frame, [a, Math.max(a + 1, b)], [from, to], { ...clampOptions, easing: ease });
  const snap = (at: number) => frame < at ? 0 : spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const bounded = (v: number) => Math.max(0, Math.min(1, v));

  let zoom = tween(0, rightEnd, 1.15, 1.18);
  let panX = 0;
  let panY = 0;
  if (frame >= inspectionAt) {
    panX = tween(inspectionAt, transparentEnd, 0, 20);
    panY = tween(inspectionAt, transparentEnd, 0, 8);
  }
  if (frame >= trackingAt) {
    zoom = tween(trackingAt, decentralizedEnd, 1.18, 1.08);
    panX = tween(trackingAt, decentralizedEnd, 20, -60);
    panY = tween(trackingAt, decentralizedEnd, 8, 0);
  }
  if (frame >= decentralizedEnd) {
    zoom = tween(decentralizedEnd, nobodyAt, 1.08, 1);
    panX = tween(decentralizedEnd, nobodyAt, -60, 0);
    panY = 0;
  }
  if (frame >= nobodyAt) {
    zoom = tween(nobodyAt, votesEnd, 1, 1.10);
    panX = 0;
  }
  if (frame >= soAt) zoom = tween(soAt, questionEnd, 1.10, 1);
  zoom = Math.max(1, Math.min(1.18, zoom));

  const dock = tween(0, rightEnd);
  const inspection = tween(transparentAt, transparentAt + 15) * (1 - tween(transparentEnd + 6, trackingAt));
  const mismatch = frame >= changeAt;
  const changed = tween(changeAt, changeAt + 10);
  const alertEnter = bounded(snap(changeAt));
  const statusEnter = bounded(snap(perfectAt));
  const contextEnter = bounded(snap(decentralizedAt));
  const questionEnter = snap(electionsAt);
  const questionOpacity = bounded(questionEnter);
  const frameEnter = bounded(snap(whyAt));
  const qualifyEnter = bounded(snap(changeAt + 8));
  const recordId = props.inheritedRecordId ?? props.recordId ?? 'R-024';
  const contentScale = Math.min(width / 1920, height / 1080);
  const meshOpacity = 1 - tween(soAt, questionEnd, 0, 0.055);
  const floatShadow = '0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.4)';

  const nodeCard = (node: typeof NODES[number], i: number) => {
    const entranceAt = i === 1 ? 0 : perfectAt + ([0, 0, 1, 2, 3, 4][i] * 5);
    const entrance = i === 1 ? 1 : snap(entranceAt);
    const opacity = i === 1 ? 1 : bounded(entrance);
    const suspect = i === 4;
    const isChanged = suspect && mismatch;
    const isInspected = frame >= transparentAt + i * 5 && frame <= trackingAt;
    const statusColor = isChanged ? C.softCoral : C.emerald;
    const arrivalAt = [trackingAt + 37, trackingAt + 11, decentralizedEnd, trackingAt + 54, trackingAt + 65, trackingAt + 74][i];
    const arrival = tween(arrivalAt, arrivalAt + 7) * (1 - tween(arrivalAt + 9, arrivalAt + 29));
    const headerState = isChanged ? 'DIFFERS' : 'MATCH';
    const inspectionSweep = interpolate(frame, [transparentAt + i * 5, transparentAt + 27 + i * 5], [-140, 310], clampOptions);
    const inspectOverlay = isInspected ? inspection * 0.24 : 0;
    const rowValues = ['17', isChanged ? '19' : '18', '19'];
    return (
      <div key={node.label} style={{ position: 'absolute', left: node.x - 150, top: node.y - 87, width: 300, height: 174, borderRadius: 24, opacity, transform: 'translateY(' + ((1 - entrance) * 14) + 'px)', transformOrigin: '50% 50%', zIndex: 3 }}>
        <mg.Card width={300} height={174} mode="dark" tilt={0} style={{ position: 'relative', width: 300, height: 174, padding: 0, boxSizing: 'border-box', borderRadius: 24, overflow: 'hidden', background: 'rgba(15,23,42,0.85)', backdropFilter: 'blur(14px)', border: '1px solid rgba(255,255,255,0.10)', boxShadow: isChanged ? '0 20px 60px rgba(255,90,54,0.30), 0 8px 24px rgba(0,0,0,0.4)' : floatShadow }}>
          <div style={{ position: 'absolute', inset: 0, borderRadius: 24, background: 'radial-gradient(ellipse at 12% 0%, rgba(49,94,255,0.22), transparent 72%)', pointerEvents: 'none' }} />
          <div style={{ position: 'absolute', inset: 0, borderRadius: 24, border: '2px solid ' + (isChanged ? C.softCoral : C.blue), opacity: isChanged ? 0.82 * alertEnter : arrival * 0.8 + inspection * 0.18, pointerEvents: 'none' }} />
          <div style={{ position: 'absolute', left: 18, top: 13, right: 17, height: 29, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ fontFamily: tight, fontSize: 26, lineHeight: 1, fontWeight: 600, color: C.white, letterSpacing: '0.035em' }}>{node.label}</span>
            <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontFamily: mono, fontSize: 13, fontWeight: 500, color: statusColor, letterSpacing: '0.025em' }}>
              {isChanged ? <Alert color={statusColor} size={16} /> : <Check color={statusColor} size={16} />}{headerState}
            </span>
          </div>
          <div style={{ position: 'absolute', left: 18, right: 18, top: 50, height: 25, borderRadius: 20, background: 'rgba(255,255,255,0.045)', display: 'flex', alignItems: 'center', padding: '0 10px', boxSizing: 'border-box', gap: 9, fontFamily: mono, fontSize: 17, fontWeight: 500, fontVariantNumeric: 'tabular-nums', color: '#C9D6EA' }}>
            <span style={{ color: '#94A8C6', fontSize: 13 }}>01</span><span>R-023</span><span style={{ marginLeft: 'auto', opacity: 0.7 }}>:</span><span>{rowValues[0]}</span><Check color={C.emerald} size={15} />
          </div>
          <div style={{ position: 'absolute', left: 18, right: 18, top: 80, height: 48, display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 180, height: 48, flexShrink: 0, borderRadius: 20, background: isChanged ? 'rgba(255,90,54,0.20)' : i === 1 ? 'rgba(49,94,255,0.07)' : 'rgba(49,94,255,0.18)', border: '1px solid ' + (isChanged ? 'rgba(243,107,89,0.75)' : 'rgba(96,143,255,0.40)'), display: 'flex', alignItems: 'center', gap: 10, padding: '0 12px', boxSizing: 'border-box', color: isChanged ? '#FFD8CE' : '#E1EAFF', fontFamily: mono, fontSize: 21, fontWeight: 500, fontVariantNumeric: 'tabular-nums', overflow: 'hidden' }}>
              <svg width="16" height="8" viewBox="0 0 16 8" style={{ flexShrink: 0 }}><path d="M2 4h12" stroke={isChanged ? C.softCoral : '#82AAFF'} strokeWidth="3" strokeLinecap="round" /></svg>
              <span style={{ whiteSpace: 'nowrap', opacity: i === 1 ? 0 : 1 }}>{recordId}</span>
            </div>
            <span style={{ fontFamily: mono, fontSize: 23, fontWeight: 500, fontVariantNumeric: 'tabular-nums', color: isChanged ? '#FFD0C6' : C.white, minWidth: 30 }}>{rowValues[1]}</span>
            {isChanged ? <Alert color={C.softCoral} size={18} /> : <Check color={C.emerald} size={18} />}
          </div>
          <div style={{ position: 'absolute', left: 18, right: 18, top: 134, height: 25, borderRadius: 20, background: 'rgba(255,255,255,0.045)', display: 'flex', alignItems: 'center', padding: '0 10px', boxSizing: 'border-box', gap: 9, fontFamily: mono, fontSize: 17, fontWeight: 500, fontVariantNumeric: 'tabular-nums', color: '#C9D6EA' }}>
            <span style={{ color: '#94A8C6', fontSize: 13 }}>03</span><span>R-025</span><span style={{ marginLeft: 'auto', opacity: 0.7 }}>:</span><span>{rowValues[2]}</span><Check color={C.emerald} size={15} />
          </div>
          <div style={{ position: 'absolute', top: 46, bottom: 10, left: inspectionSweep, width: 125, borderRadius: 24, background: 'linear-gradient(90deg, transparent, rgba(92,177,255,0.75), transparent)', opacity: inspectOverlay, pointerEvents: 'none' }} />
        </mg.Card>
        {suspect && frame >= secretlyAt && frame < changeAt + 14 ? (
          <svg width="306" height="180" viewBox="0 0 306 180" style={{ position: 'absolute', left: -3, top: -3, overflow: 'visible', pointerEvents: 'none', opacity: tween(secretlyAt, secretlyAt + 12) * (1 - tween(changeAt, changeAt + 14)) }}>
            <rect x="3" y="3" width="300" height="174" rx={24} ry={24} fill="none" stroke={C.softCoral} strokeWidth="2" pathLength={1} strokeDasharray="0.025 0.02" strokeDashoffset={-frame * 0.002} opacity="0.9" />
          </svg>
        ) : null}
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ background: '#F3F5F8', overflow: 'hidden', fontFamily: sans }}>
      <div style={{ position: 'absolute', left: (width - 1920 * contentScale) / 2, top: (height - 1080 * contentScale) / 2, width: 1920, height: 1080, transform: 'scale(' + contentScale + ')', transformOrigin: '0 0', color: C.ink, overflow: 'hidden' }}>
        <AbsoluteFill style={{ background: 'linear-gradient(155deg, #FAFBFF 0%, #F3F5F8 31%, #E5ECFA 66%, #F9FBFE 100%)' }} />
        <AbsoluteFill style={{ opacity: 0.4 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ pointerEvents: 'none', background: 'radial-gradient(60% 72% at ' + (68 + 3 * Math.sin(frame / 180)) + '% 25%, rgba(0,102,255,0.14), transparent 71%), radial-gradient(44% 54% at 19% 85%, rgba(0,167,123,0.08), transparent 74%), radial-gradient(40% 40% at 83% 78%, rgba(255,90,54,' + (0.025 + changed * 0.035) + '), transparent 75%)' }} />

        <div style={{ position: 'absolute', left: 115, top: 150, width: 1690, height: 850, borderRadius: 28, background: 'rgba(255,255,255,0.75)', backdropFilter: 'blur(14px)', border: '1px solid rgba(0,0,0,0.08)', boxSizing: 'border-box', boxShadow: '0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.10)', overflow: 'hidden' }}>
          <div style={{ position: 'absolute', inset: 0, borderRadius: 28, background: 'radial-gradient(60% 70% at 50% 36%, rgba(255,255,255,0.96), transparent 82%), linear-gradient(135deg, rgba(49,94,255,0.035), transparent 48%, rgba(0,167,123,0.035))' }} />
          <svg width="1690" height="850" viewBox="0 0 1690 850" style={{ position: 'absolute', inset: 0, opacity: 0.065 }}>
            {Array.from({ length: 16 }, (_, i) => <path key={'v' + i} d={'M ' + (80 + i * 102) + ' 84 V 760'} stroke={C.blue} strokeWidth="1" strokeLinecap="round" />)}
            {Array.from({ length: 8 }, (_, i) => <path key={'h' + i} d={'M 68 ' + (104 + i * 90) + ' H 1622'} stroke={C.blue} strokeWidth="1" strokeLinecap="round" />)}
          </svg>
        </div>

        <div style={{ position: 'absolute', left: 116, top: 80, zIndex: 10, fontFamily: sans, fontSize: 23, lineHeight: '28px', fontWeight: 500, letterSpacing: '0.15em', color: C.record }}>THE APPEAL</div>
        <div style={{ position: 'absolute', left: 116, top: 112, zIndex: 10, fontFamily: tight, fontSize: 52, lineHeight: '58px', fontWeight: 600, letterSpacing: '-0.045em', color: C.ink }}>A shared record</div>

        <div style={{ position: 'absolute', left: 156, top: 193, display: 'flex', alignItems: 'center', gap: 10, zIndex: 6 }}>
          <span style={{ width: 8, height: 8, borderRadius: 9999, background: C.record, boxShadow: '0 0 14px rgba(49,94,255,0.3)' }} />
          <span style={{ fontFamily: sans, fontSize: 22, fontWeight: 500, letterSpacing: '0.085em', color: '#526683' }}>ILLUSTRATIVE COPIES</span>
        </div>
        <div style={{ position: 'absolute', right: 158, top: 193, fontFamily: mono, fontSize: 17, lineHeight: '27px', color: C.slate, fontVariantNumeric: 'tabular-nums', zIndex: 6 }}>06 COPIES / 01 SHARED RECORD</div>

        <AbsoluteFill style={{ opacity: meshOpacity, pointerEvents: 'none' }}>
          <mg.CameraRig zoom={zoom} x={panX} y={panY} style={{ position: 'absolute', inset: 0, width: 1920, height: 1080, transformOrigin: '960px 540px' }}>
            <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{ position: 'absolute', inset: 0, overflow: 'visible', zIndex: 1 }}>
              <defs>
                <filter id="mgGlow" x="-120%" y="-120%" width="340%" height="340%"><feGaussianBlur stdDeviation="4" result="blur" /><feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge></filter>
                <filter id="mgSoft" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="7" /></filter>
                <linearGradient id="meshLinkBlue" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#77A6FF" /><stop offset="50%" stopColor={C.record} /><stop offset="100%" stopColor="#77A6FF" /></linearGradient>
              </defs>
              {LINKS.map((l, i) => {
                const reveal = tween(22 + l.delay, 64 + l.delay);
                const d = pathFor(l);
                const canRun = frame >= 42 + l.delay;
                const phase = ((Math.max(0, frame - 42 - l.delay) / (104 + i * 7)) + random('mesh-packet-' + i) * 0.75) % 1;
                const t = l.reverse ? 1 - phase : phase;
                const p = pointOn(l, t);
                const tail = pointOn(l, Math.max(0, Math.min(1, t + (l.reverse ? 0.075 : -0.075))));
                const endpointsFade = Math.min(1, phase * 12, (1 - phase) * 12);
                const packetOpacity = canRun ? endpointsFade * reveal * (1 - changed * 0.34) : 0;
                const dash = reveal + ' 1';
                return (
                  <g key={i}>
                    <path d={d} fill="none" stroke={C.blue} strokeWidth="10" opacity={0.09 * reveal} filter="url(#mgSoft)" strokeLinecap="round" pathLength={1} strokeDasharray={dash} />
                    <path d={d} fill="none" stroke="#CAD9F5" strokeWidth="3.6" opacity={0.92 * reveal} strokeLinecap="round" pathLength={1} strokeDasharray={dash} />
                    <path d={d} fill="none" stroke="url(#meshLinkBlue)" strokeWidth="1.5" opacity={0.65 * reveal} strokeLinecap="round" pathLength={1} strokeDasharray={dash} />
                    <path d={'M ' + tail.join(' ') + ' L ' + p.join(' ')} fill="none" stroke={C.blue} strokeWidth="5" strokeLinecap="round" opacity={packetOpacity * 0.8} filter="url(#mgGlow)" />
                    <circle cx={p[0]} cy={p[1]} r="4" fill={C.record} opacity={packetOpacity} />
                    <circle cx={p[0]} cy={p[1]} r="1.7" fill="#FFFFFF" opacity={packetOpacity} />
                  </g>
                );
              })}
              {frame >= trackingAt && frame <= decentralizedEnd + 18 ? (() => {
                const l = LINKS[1];
                const progress = tween(trackingAt, decentralizedEnd);
                const p = pointOn(l, progress);
                const tail = pointOn(l, Math.max(0, progress - 0.13));
                const alpha = tween(trackingAt, trackingAt + 8) * (1 - tween(decentralizedEnd, decentralizedEnd + 18));
                return <g opacity={alpha}><path d={pathFor(l)} stroke={C.blue} strokeWidth="3" fill="none" strokeLinecap="round" pathLength={1} strokeDasharray={progress + ' 1'} opacity="0.7" /><path d={'M ' + tail.join(' ') + ' L ' + p.join(' ')} stroke={C.blue} strokeWidth="7" fill="none" strokeLinecap="round" filter="url(#mgGlow)" /><circle cx={p[0]} cy={p[1]} r="5" fill="#FFFFFF" stroke={C.record} strokeWidth="2" filter="url(#mgGlow)" /></g>;
              })() : null}
              {NODES.map((n, i) => {
                const at = decentralizedAt + i * 5;
                const t = interpolate(frame, [at, at + 34], [0, 1], clampOptions);
                return <circle key={'pulse' + i} cx={n.x} cy={n.y} r={38 + t * 132} stroke={C.blue} strokeWidth="1.7" fill="none" opacity={frame < at ? 0 : (1 - t) * 0.18} />;
              })}
            </svg>

            {NODES.map(nodeCard)}

            <div style={{ position: 'absolute', left: 828, top: 393 - (1 - dock) * 92, width: 180, height: 48, borderRadius: 20, zIndex: 5, background: 'linear-gradient(125deg, #0066FF 0%, #315EFF 70%, #4875FF 100%)', border: '1px solid rgba(255,255,255,0.46)', boxSizing: 'border-box', boxShadow: '0 16px 38px rgba(0,102,255,0.32), 0 3px 10px rgba(0,0,0,0.15), inset 0 1px 0 rgba(255,255,255,0.32)', display: 'flex', alignItems: 'center', padding: '0 12px', gap: 10, color: '#FFFFFF', fontFamily: mono, fontSize: 21, fontWeight: 500, fontVariantNumeric: 'tabular-nums', overflow: 'hidden' }}>
              <svg width="16" height="8" viewBox="0 0 16 8" style={{ flexShrink: 0 }}><path d="M2 4h12" stroke="#FFFFFF" strokeWidth="3" strokeLinecap="round" /></svg>
              <span style={{ whiteSpace: 'nowrap' }}>{recordId}</span>
            </div>

            <div style={{ position: 'absolute', left: 653, top: 511, width: 614, height: 67, zIndex: 4, opacity: statusEnter, transform: 'translateY(' + ((1 - statusEnter) * 9) + 'px)', borderRadius: 24, background: 'rgba(255,255,255,0.94)', backdropFilter: 'blur(14px)', border: '1px solid ' + (mismatch ? 'rgba(255,90,54,0.24)' : 'rgba(0,167,123,0.19)'), boxShadow: mismatch ? '0 14px 40px rgba(255,90,54,0.17), 0 4px 14px rgba(23,35,59,0.06)' : '0 14px 40px rgba(0,167,123,0.12), 0 4px 14px rgba(0,102,255,0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 12 }}>
              {mismatch ? <Alert color={C.coral} size={28} /> : <Check color={C.emerald} size={28} />}
              <span style={{ fontFamily: tight, fontSize: 27, fontWeight: 600, letterSpacing: '0.018em', color: mismatch ? '#B73C2B' : '#007B5B' }}>{mismatch ? 'RECORD MISMATCH VISIBLE' : 'RECORD COPIES MATCH'}</span>
            </div>
            <div style={{ position: 'absolute', left: 600, top: 581, width: 720, textAlign: 'center', zIndex: 4, fontFamily: mono, fontSize: 16, lineHeight: '22px', fontWeight: 500, fontVariantNumeric: 'tabular-nums', color: mismatch ? '#B74836' : '#577094', opacity: mismatch ? alertEnter : contextEnter }}>
              {mismatch ? 'COPY E: 18 → 19  /  FIVE COPIES STILL READ 18' : 'SAME RECORD · SIX COPIES · NO CENTRAL COPY'}
            </div>
          </mg.CameraRig>
        </AbsoluteFill>

        <div style={{ position: 'absolute', left: 620, top: 830, width: 680, height: 48, zIndex: 7, opacity: qualifyEnter, transform: 'translateY(' + ((1 - qualifyEnter) * 10) + 'px)', borderRadius: 24, background: 'rgba(255,249,232,0.95)', backdropFilter: 'blur(14px)', border: '1px solid rgba(232,173,54,0.38)', boxShadow: '0 12px 32px rgba(232,173,54,0.12), 0 4px 12px rgba(0,102,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
          <Alert color="#B57A12" size={21} />
          <span style={{ fontFamily: sans, fontSize: 22, lineHeight: '26px', fontWeight: 500, color: '#855B17', letterSpacing: '-0.025em' }}>Tamper resistance ≠ guaranteed immutability</span>
        </div>

        {frame >= whyAt ? (
          <div style={{ position: 'absolute', left: 274, top: 269, width: 1372, height: 549, zIndex: 6, pointerEvents: 'none', opacity: frameEnter * 0.88, borderRadius: 24, transform: 'scale(' + (1.012 - frameEnter * 0.012) + ')', transformOrigin: '50% 50%' }}>
            <mg.FocusFrame color={C.coral} borderRadius={24} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', borderRadius: 24 }}>
              <div style={{ width: 1372, height: 549, borderRadius: 24 }} />
            </mg.FocusFrame>
            <svg width="1372" height="549" viewBox="0 0 1372 549" style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
              {['M0 58V24Q0 0 24 0H78', 'M1294 0H1348Q1372 0 1372 24V58', 'M1372 491V525Q1372 549 1348 549H1294', 'M78 549H24Q0 549 0 525V491'].map((d, i) => <path key={i} d={d} fill="none" stroke={C.coral} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={tween(whyAt + i * 4, whyAt + i * 4 + 26) + ' 1'} />)}
            </svg>
