        <div style={{ position: 'absolute', left: 620, top: 898, width: 680, height: 54, zIndex: 8, opacity: questionOpacity, transform: 'translateY(' + ((1 - questionEnter) * 14) + 'px) scale(' + (0.975 + questionEnter * 0.025) + ')', transformOrigin: '50% 50%', borderRadius: 24, background: 'rgba(255,255,255,0.88)', backdropFilter: 'blur(14px)', border: '1px solid rgba(255,90,54,0.32)', boxShadow: '0 20px 60px rgba(255,90,54,0.2), 0 6px 18px rgba(0,102,255,0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 13 }}>
          <span style={{ width: 29, height: 29, borderRadius: 9999, background: 'rgba(255,90,54,0.11)', color: '#C94A31', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: tight, fontSize: 21, fontWeight: 600 }}>?</span>
          <span style={{ color: C.ink, fontFamily: tight, fontSize: 28, fontWeight: 600, letterSpacing: '0.025em' }}>ENOUGH FOR AN ELECTION?</span>
