const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const ease = Easing.inOut(Easing.cubic);
const cueDefaults = [
  { index: 44, word: 'Because', at: 0 }, { index: 45, word: 'the', at: 28 },
  { index: 46, word: 'biggest', at: 40 }, { index: 47, word: 'problem', at: 65 },
  { index: 48, word: 'with', at: 90 }, { index: 49, word: 'elections', at: 99 },
  { index: 50, word: "isn't", at: 162 }, { index: 51, word: 'storing', at: 183 },
  { index: 52, word: 'the', at: 209 }, { index: 53, word: 'votes.', at: 216 },
  { index: 54, word: "It's", at: 284 }, { index: 55, word: 'making', at: 292 },
  { index: 56, word: 'sure', at: 312 }, { index: 57, word: 'the', at: 329 },
  { index: 58, word: 'right', at: 373 }, { index: 59, word: 'person', at: 398 },
  { index: 60, word: 'is', at: 423 }, { index: 61, word: 'casting', at: 430 },
  { index: 62, word: 'the', at: 454 }, { index: 63, word: 'vote', at: 461 },
];

const Check = ({ color = C.emerald, size = 24 }: { color?: string; size?: number }) => (
