export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const normalize = (s: string) => s.toLowerCase().replace(/[^a-z]/g, '');
  const at = (index: number) => {
    const fallback = cueDefaults.find(c => c.index === index)!;
    const explicit = cues.find(c => {
      const candidate = c.wordIndex ?? c.word_index ?? c.index ?? c.id;
      return candidate !== undefined && Number(String(candidate).replace(/^W/i, '')) === index;
    });
    const positional = cues[index - 44];
    const positionalMatch = positional && normalize(positional.word ?? positional.text ?? '') === normalize(fallback.word) ? positional : undefined;
    const match = explicit ?? positionalMatch;
    return match?.startFrame ?? match?.start_frame ?? fallback.at;
  };
  const progress = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const enter = (delay: number) => frame < delay ? 0 : spring({ frame: frame - delay, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const mix = (a: number, b: number, p: number) => a + (b - a) * p;
  const fIsnt = at(50);
  const fStore = at(51);
  const fVotes = at(53);
