  const cameraTrack = progress(fIts, fPerson + 29);
  const pullback = progress(fCasting, fVote + 17);
  const ambient = progress(fVote + 18, finalReturnAt - 1);
  const handoff = progress(finalReturnAt, endFrame);
  const desiredZoom = (1.08 - 0.01 * storageSettle - 0.01 * cameraTrack) * (1 - pullback) + (1 + 0.01 * ambient * (1 - handoff)) * pullback;
  const desiredX = (5 * (1 - storageSettle) - 55 * cameraTrack) * (1 - pullback);
  const desiredY = (-40 + 5 * storageSettle) * (1 - pullback);
  const stage = { x: 115, y: 150, w: 1690, h: 850 };
