  const oy = stage.h / 2;
  const bounds = { left: 105, right: 1585, top: 45, bottom: 805 };
  const zoom = Math.min(desiredZoom, 1.3, 1720 / (bounds.right - bounds.left), 920 / (bounds.bottom - bounds.top));
  const projectedL = stage.x + ox + (bounds.left - ox) * zoom;
  const projectedR = stage.x + ox + (bounds.right - ox) * zoom;
  const projectedT = stage.y + oy + (bounds.top - oy) * zoom;
