  const panX = clamp(desiredX, Math.max(-120, 100 - projectedL), Math.min(120, 1820 - projectedR));
  const panY = clamp(desiredY, Math.max(-80, 80 - projectedT), Math.min(80, 1000 - projectedB));
  const identityLift = progress(fIts, fSure + 20);
  const recordBoost = progress(fStore, fVotes + 12);
  const qualifier = progress(fIsnt, fStore + 16);
  const checkReveal = clamp(enter(fStore), 0, 1);
  const recordID = (props.recordId || 'R-017').slice(0, 9);
  const focusIntro = progress(at(47), at(47) + 18);
  const focusOpacity = focusIntro * (1 - 0.24 * pullback);
