import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[]; recordId?: string; inheritedRecordId?: string };

const C = { blue: "#315EFF", blueLight: "#9CBBFF", coral: "#F36B59", white: "#F8FAFC", muted: "#B4C2DA", midnight: "#10192B" };
const UI = '"Inter", "Arial", sans-serif';
const TIGHT = '"Inter Tight", "Inter", "Arial", sans-serif';
const MONO = '"IBM Plex Mono", "SFMono-Regular", monospace';
const BLUE_SHADOW = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.4)";
const CORAL_SHADOW = "0 20px 60px rgba(255,90,54,0.2), 0 8px 24px rgba(0,0,0,0.4)";
const GLASS: React.CSSProperties = { borderRadius: 24, background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxSizing: "border-box" };
const ease = Easing.bezier(0.22, 0.68, 0.24, 1);
const ramp = (frame: number, from: number, to: number) => interpolate(frame, [from, Math.max(from + 1, to)], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const enter = (frame: number, delay: number, fps: number) => spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });

const RecordToken: React.FC<{ id: string; small?: boolean; emphasis?: number }> = ({ id, small = false, emphasis = 0 }) => (
  <div style={{ width: small ? 80 : 88, height: small ? 58 : 64, borderRadius: 24, boxSizing: "border-box", background: `linear-gradient(145deg, rgba(87,132,255,${0.96 + emphasis * 0.04}), #315EFF 62%, #1645D8)`, border: "1px solid rgba(209,226,255,0.56)", boxShadow: "0 12px 32px rgba(49,94,255,0.32), inset 0 1px 0 rgba(255,255,255,0.27)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 9 }}>
    <div style={{ width: 26, height: 4, borderRadius: 9999, background: "#EDF4FF", boxShadow: "0 0 10px rgba(230,239,255,0.30)" }} />
    <span style={{ fontFamily: MONO, fontWeight: 500, fontSize: small ? 11 : 12, lineHeight: 1, color: "#FFFFFF", letterSpacing: 0.5, fontVariantNumeric: "tabular-nums", maxWidth: small ? 70 : 80, whiteSpace: "nowrap" }}>{id}</span>
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number, word: string) => {
    const match = cues.find((c) => c.wordIndex === index || c.index === index) || cues.find((c) => String(c.word || c.text || "").toLowerCase().replace(/[^a-z]/g, "") === word);
    return typeof match?.startFrame === "number" ? match.startFrame : fallback;
  };
  const forcedAt = cue(66, 36, "forced");
  const manipulatedAt = cue(68, 64, "manipulated");
  const andAt = cue(69, 147, "and");
  const blockchainAt = cue(70, 155, "blockchain");
  const doesntAt = cue(71, 184, "doesnt");
  const solveAt = cue(72, 203, "solve");
  const letsAt = cue(74, 276, "lets");
  const startAt = cue(75, 288, "start");
  const obviousAt = cue(78, 327, "obvious");
  const advantageAt = cue(79, 355, "advantage");
  const recordId = props.inheritedRecordId || props.recordId || "V-0042";
  const shotFrame = Math.min(frame, 438);

  // All camera coordinates are absolute design-space coordinates around (960,540).
  const cameraAt = (f: number) => {
    if (f < 24) return { z: 1.03, x: 0, y: 0 };
    if (f <= 100) { const p = ramp(f, 24, 100); return { z: mix(1.03, 1.08, p), x: -20 * p, y: -24 * p }; }
    if (f <= 231) { const p = ramp(f, 101, 231); return { z: mix(1.08, 1, p), x: -20 * (1 - p), y: -24 * (1 - p) }; }
    if (f < letsAt) return { z: 1, x: 0, y: 0 };
    if (f <= 399) { const p = ramp(f, letsAt, 399); return { z: mix(1, 1.18, p), x: 20 * p, y: 38 * p }; }
    return { z: 1.18, x: 20, y: 38 };
  };
  const camera = cameraAt(shotFrame);
  const consoleSpring = enter(frame, 2, fps);
  const consoleOpacity = Math.min(1, Math.max(0, consoleSpring));
  const consoleY = 10 * (1 - consoleSpring);
  const historySpring = enter(frame, 2, fps);
  const identitySpring = enter(frame, 6, fps);
  const pressureSpring = enter(frame, 10, fps);
  const identityReveal = Math.min(1, Math.max(0, identitySpring));
  const pressureReveal = Math.min(1, Math.max(0, pressureSpring));
  const forcedSpring = enter(frame, forcedAt, fps);
  const manipulatedSpring = enter(frame, manipulatedAt, fps);
  const conclusion = ramp(frame, doesntAt, solveAt + 19);
  const historyFocus = ramp(frame, letsAt, obviousAt + 12);
  const nextLight = ramp(frame, 400, Math.min(438, Math.max(401, durationInFrames - 1)));
  const blueRecognition = ramp(frame, blockchainAt, blockchainAt + 12) * (1 - ramp(frame, doesntAt, solveAt));
  const risksOpacity = 1 - historyFocus * 0.19;
  const routeProgress = ramp(frame, 24, 100);

  // A single inherited focus window travels upstream, then examines both empty fields.
  const queryTarget = { x: 349, y: 231, w: 67, h: 72 };
  const tokenTarget = { x: 226, y: 380, w: 96, h: 72 };
  const railTarget = { x: 308, y: 586, w: 46, h: 60 };
  const identityTarget = { x: 1173, y: 533, w: 325, h: 112 };
  const pressureTarget = { x: 1173, y: 708, w: 325, h: 112 };
  const targets = [queryTarget, tokenTarget, railTarget, identityTarget, pressureTarget, identityTarget, pressureTarget];
  const focusTimes = [2, 24, 35, forcedAt + 14, manipulatedAt + 25, doesntAt + 9, solveAt + 16];
  let reticle = targets[0];
  for (let i = 1; i < targets.length; i++) {
    if (frame >= focusTimes[i - 1]) {
      const p = ramp(frame, focusTimes[i - 1], focusTimes[i]);
      reticle = { x: mix(targets[i - 1].x, targets[i].x, p), y: mix(targets[i - 1].y, targets[i].y, p), w: mix(targets[i - 1].w, targets[i].w, p), h: mix(targets[i - 1].h, targets[i].h, p) };
    }
  }
  const reticleFade = consoleOpacity * (1 - 0.50 * ramp(frame, 101, andAt)) * (1 - ramp(frame, letsAt, startAt + 14));
  const lastSegment = frame >= doesntAt && frame < letsAt;
  const inspectionOpacity = reticleFade * (lastSegment ? 1.4 : 1);
  const advantageSpring = enter(frame, advantageAt, fps);

  // Validate every card and the maximum spring excursion for all 439 frames.
  const safeZoneValidated = React.useMemo(() => {
    const bounds = [
      { x: 230, y: 384, w: 88, h: 64, delay: 2 },
      { x: 350, y: 232, w: 1170, h: 70, delay: 2 },
      { x: 350, y: 340, w: 1170, h: 150, delay: 2 },
      { x: 350, y: 515, w: 1170, h: 150, delay: 6 },
      { x: 350, y: 690, w: 1170, h: 150, delay: 10 },
      { x: 350, y: 858, w: 1170, h: 38, delay: 2 },
    ];
    for (let f = 0; f < 439; f++) {
      const cam = cameraAt(f);
      const sy = 10 * (1 - enter(f, 2, fps));
      for (const b of bounds) {
        const dy = b.y === 340 || b.y === 515 || b.y === 690 ? 8 * (1 - enter(f, b.delay, fps)) : 0;
        const left = 960 + (b.x - 960) * cam.z + cam.x;
        const right = 960 + (b.x + b.w - 960) * cam.z + cam.x;
        const top = 540 + (b.y + sy + dy - 540) * cam.z + cam.y;
        const bottom = 540 + (b.y + b.h + sy + dy - 540) * cam.z + cam.y;
        if (left < 100 || right > 1820 || top < 80 || bottom > 1000) return false;
      }
    }
    return true;
  }, [fps, letsAt]);

  const evidenceField = (label: string, accent: number) => (
    <div style={{ position: "absolute", left: 831, top: 26, width: 309, height: 98, borderRadius: 24, background: "rgba(7,12,24,0.62)", border: `1px solid rgba(243,107,89,${0.22 + accent * 0.15})`, boxSizing: "border-box", boxShadow: "inset 0 2px 14px rgba(0,0,0,0.24)" }}>
      <div style={{ position: "absolute", top: 15, left: 19, fontFamily: MONO, fontSize: 17, lineHeight: 1, fontWeight: 500, letterSpacing: 1.1, color: C.muted }}>{label}</div>
      <div style={{ position: "absolute", left: 18, right: 18, top: 43, bottom: 13, borderRadius: 24, border: "1px dashed rgba(243,107,89,0.33)", background: "rgba(15,23,42,0.20)" }} />
    </div>
  );

  return (
    <AbsoluteFill style={{ background: C.midnight, overflow: "hidden", fontFamily: UI, color: C.white }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transform: `scale(${width / 1920}, ${height / 1080})`, transformOrigin: "0 0", overflow: "hidden", borderRadius: 24 }} data-safe-zone-validated={safeZoneValidated ? "true" : "false"}>
        {/* 1. Saturated midnight field. */}
        <AbsoluteFill style={{ borderRadius: 24, background: "linear-gradient(155deg, #070A12 0%, #10192B 42%, #142442 72%, #080F1E 100%)" }} />
        {/* 2. Architectural grid. */}
        <AbsoluteFill style={{ opacity: 0.19, borderRadius: 24 }}><mg.GridBackground mode="dark" gridSize={48} /></AbsoluteFill>
        {/* 3. Directional illumination. */}
        <AbsoluteFill style={{ borderRadius: 24, background: `radial-gradient(62% 72% at ${69 - historyFocus * 12}% ${29 + historyFocus * 8}%, rgba(49,94,255,${0.18 + historyFocus * 0.1 + nextLight * 0.06}), transparent 70%), radial-gradient(44% 62% at 13% 75%, rgba(243,107,89,0.11), transparent 75%)` }} />
        <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: "linear-gradient(180deg, rgba(7,10,18,0.15), transparent 40%, rgba(7,10,18,0.26))" }} />

        {/* Static inspection housing: the stage edges do not move with the camera. */}
        <div style={{ ...GLASS, position: "absolute", left: 115, top: 170, width: 1690, height: 850, opacity: consoleOpacity, background: "linear-gradient(145deg, rgba(15,23,42,0.85), rgba(16,25,43,0.72))", boxShadow: "0 20px 60px rgba(0,102,255,0.14), 0 8px 24px rgba(0,0,0,0.4)", overflow: "hidden" }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: `radial-gradient(80% 53% at 48% 22%, rgba(49,94,255,${0.06 + 0.12 * historyFocus}), transparent 80%)` }} />
          <div style={{ position: "absolute", left: 35, top: 30, fontFamily: MONO, fontSize: 12, fontWeight: 500, color: "#98AECB", letterSpacing: 2 }}>04 / INSPECTION</div>
          <div style={{ position: "absolute", right: 35, bottom: 24, fontFamily: MONO, fontSize: 12, color: "#97AFD0", letterSpacing: 2 }}>READ-ONLY QUERY</div>
        </div>
        <div style={{ position: "absolute", inset: 0, opacity: 0.60 }}>
          <mg.Marker x={145} y={965} variant="cross" color={C.blue} />
          <mg.Marker x={1774} y={203} variant="cross" color={C.coral} />
          <mg.Marker x={1774} y={965} variant="cross" color={C.blue} />
        </div>

        {/* 4. Center-pivot camera; heading deliberately excluded. */}
        <mg.CameraRig zoom={camera.z} x={camera.x} y={camera.y} style={{ position: "absolute", inset: 0, width: 1920, height: 1080, transformOrigin: "960px 540px" }}>
          <div style={{ position: "absolute", inset: 0, opacity: consoleOpacity, transform: `translateY(${consoleY}px)`, transformOrigin: "960px 540px" }}>
