              <path d="M332 565 V520 Q332 503 350 503 H1137 Q1159 503 1159 525 V557 Q1159 573 1176 573 H1181" stroke={C.coral} strokeOpacity={0.28 * risksOpacity} strokeWidth={2} strokeLinecap="round" fill="none" />
              <path d="M332 740 V693 Q332 677 350 677 H1137 Q1159 677 1159 700 V732 Q1159 748 1176 748 H1181" stroke={C.coral} strokeOpacity={0.28 * risksOpacity} strokeWidth={2} strokeLinecap="round" fill="none" />
              <path d="M274 450 V476 Q274 500 298 500 H310 Q332 500 332 522 V764" pathLength={1} stroke={C.coral} strokeWidth={3} strokeLinecap="round" fill="none" strokeDasharray="0.12 1" strokeDashoffset={-routeProgress * 0.83} opacity={frame >= 24 && frame <= 110 ? 0.65 : 0} filter="url(#mgGlow)" />
            </svg>
            <div style={{ opacity: 0.7 * risksOpacity }}>
              <mg.Marker x={332} y={503} variant="cross" color={C.coral} />
