import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const BLUE = "#315EFF";
const CORAL = "#F36B59";
const GREEN = "#00A77B";
const AMBER = "#E8AD36";
const WHITE = "#F8FAFC";
const INK = "#17233B";
const SANS = "Inter, Arial, sans-serif";
const MONO = "IBM Plex Mono, monospace";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const blueShadow = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(15,23,42,0.16)";
const glass: React.CSSProperties = {
  position: "absolute",
  borderRadius: 24,
  background: "rgba(15,23,42,0.85)",
  backdropFilter: "blur(14px)",
  border: "1px solid rgba(255,255,255,0.10)",
  boxShadow: blueShadow,
  overflow: "hidden",
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];

  const cueAt = (index: number, word: string, fallback: number): number => {
    const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
    const indexed = cues.find((c) => c.wordIndex === index || c.index === index);
    const named = cues.find((c) => normalize(c.word || c.text || "") === normalize(word));
    const found = indexed || named;
    return found && typeof found.startFrame === "number" ? found.startFrame : fallback;
  };

  const onceAt = cueAt(80, "Once", 0);
  const recordedAt = cueAt(84, "recorded", 63);
  const blockchainAt = cueAt(87, "blockchain", 105);
  const editAt = cueAt(88, "changing", 157);
  const recordAt = cueAt(90, "record", 195);
  const extremeAt = cueAt(92, "extremely", 224);
  const difficultAt = cueAt(93, "difficult", 255);
  const everyoneAt = cueAt(94, "Everyone", 315);
  const independentAt = cueAt(96, "independently", 352);
  const verifyAt = cueAt(97, "verify", 394);
  const chainCheckAt = cueAt(100, "blockchain", 435);
  const tamperedAt = cueAt(103, "tampered", 496);
  const withAt = cueAt(104, "with", 520);

  const rise = (at: number) => frame < at ? 0 : spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const fade = (at: number, length = 14) => interpolate(frame, [at, at + length], [0, 1], clamp);
  const pullStart = Math.min(281, everyoneAt);
  const pullEnd = Math.max(pullStart + 1, everyoneAt + 31);
  const cameraEase = { ...clamp, easing: Easing.inOut(Easing.cubic) };
  const pull = interpolate(frame, [pullStart, pullEnd], [0, 1], cameraEase);
  const track = interpolate(frame, [editAt, pullStart], [0, 1], cameraEase);
  const ambient = interpolate(frame, [pullEnd, 550], [0, 1], cameraEase);
  const zoom = 1.15 - 0.15 * pull + 0.015 * ambient;
  const panX = (-100 - 20 * track) * (1 - pull);
  const panY = -40 * (1 - pull);

  // CameraRig scales about the canvas center. Compensation preserves the
  // requested pre-scale mapping: screenCoordinate = (coordinate + pan) * zoom.
  const rigX = zoom * panX + (zoom - 1) * 960;
  const rigY = zoom * panY + (zoom - 1) * 540;
  const arrival = rise(onceAt + 2);
  const arrivalY = 12 * (1 - arrival);
  const editOpacity = fade(editAt, 12);
  const proposalRise = rise(editAt);
  const seal = fade(blockchainAt, 20);
  const qualifierOpacity = fade(difficultAt, 16);
  const headerFingerprintOpacity = 0.7 + 0.3 * seal;
  const verifierAAt = Math.max(pullEnd, independentAt);
  const verifierBAt = verifierAAt + 6;
  const verifyDuration = Math.max(12, chainCheckAt - verifyAt);
  const focusAt = Math.max(550, withAt + 30);
  const focus = fade(focusAt, 16);
  const footerOpacity = fade(pullEnd + 2, 18);
  const stageScale = Math.min(width / 1920, height / 1080);
  const shotProgress = Math.min(1, frame / Math.max(1, durationInFrames - 1));

  const renderVerifier = (id: string, x: number, start: number) => {
    const entrance = rise(start);
    const opacity = fade(start, 12);
    const scanStart = verifyAt + (id === "B" ? 6 : 0);
    const scanEnd = scanStart + verifyDuration;
    const scan = interpolate(frame, [scanStart, scanEnd], [0, 1], clamp);
    const fingerprintIn = fade(scanEnd, 12);
    const matchAt = Math.max(tamperedAt, scanEnd + 12);
    const matchOpacity = fade(matchAt, 12);
    const matchRise = rise(matchAt);
    const scanOpacity = interpolate(frame, [scanStart, scanStart + 5, scanEnd, scanEnd + 10], [0, 0.8, 0.8, 0], clamp);

    return (
      <div key={id} style={{ ...glass, left: x, top: 610, width: 660, height: 340, opacity, transform: "translateY(" + (12 * (1 - entrance)) + "px)" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: "radial-gradient(100% 120% at 10% 0%, rgba(49,94,255,0.22), transparent 72%)" }} />
        <div style={{ position: "absolute", left: 30, top: 24, fontSize: 25, fontWeight: 650, letterSpacing: 2, color: WHITE }}>VERIFIER {id}</div>
