            <span style={{ fontSize: 38, fontWeight: 500, lineHeight: 1 }}>0</span>
            <mg.Roll from={0} to={5} startFrame={scanStart} durationInFrames={verifyDuration} fontSize={38} color={WHITE} />
          </div>
          <span style={{ fontSize: 30, marginLeft: -27 }}>/ 05</span>
          <span style={{ fontFamily: SANS, fontSize: 16, letterSpacing: 0.8, fontWeight: 600 }}>SAMPLE RECORDS CHECKED</span>
          <span style={{ fontFamily: MONO, fontSize: 11, padding: "7px 10px", borderRadius: 9999, color: "#C8D6F7", border: "1px solid rgba(255,255,255,0.18)", whiteSpace: "nowrap" }}>DIAGRAM COUNT</span>
        </div>
        <div style={{ position: "absolute", left: 30, top: 137, width: 600, height: 95, borderRadius: 24, background: "linear-gradient(115deg, rgba(49,94,255,0.92), rgba(26,59,177,0.88))", border: "1px solid rgba(167,189,255,0.38)", boxShadow: "0 12px 34px rgba(0,102,255,0.25)", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: 22, top: 14, fontSize: 16, fontWeight: 600, letterSpacing: 1.2, color: "#E5EDFF" }}>SAMPLE HISTORY FINGERPRINT</div>
