          <div style={{ position: "absolute", left: -80 + scan * 750, top: 0, bottom: 0, width: 80, borderRadius: 24, background: "linear-gradient(90deg, transparent, rgba(198,221,255,0.62), transparent)", boxShadow: "0 0 25px rgba(94,174,255,0.45)", opacity: scanOpacity }} />
          <div style={{ position: "absolute", right: 24, bottom: 19, display: "flex", gap: 8 }}>
            {[0, 1, 2, 3, 4].map((n) => <div key={n} style={{ width: 17, height: 7, borderRadius: 9999, background: scan >= (n + 1) / 5 ? "#D6E6FF" : "rgba(201,220,255,0.25)", boxShadow: scan >= (n + 1) / 5 ? "0 0 12px rgba(189,217,255,0.35)" : "none" }} />)}
          </div>
        </div>
        <div style={{ position: "absolute", left: 30, top: 251, width: 600, height: 57, borderRadius: 24, display: "flex", alignItems: "center", gap: 14, padding: "0 19px", background: "rgba(0,167,123,0.17)", border: "1px solid rgba(66,229,175,0.4)", boxShadow: "0 10px 27px rgba(0,167,123,0.16)", opacity: matchOpacity, transform: "translateY(" + (8 * (1 - matchRise)) + "px)" }}>
          <span style={{ width: 29, height: 29, borderRadius: 9999, background: GREEN, color: "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 21, fontWeight: 700 }}>✓</span>
          <span style={{ color: "#A8F8D8", fontSize: 22, fontWeight: 650, letterSpacing: 0.55 }}>MATCH — RECORD HISTORY</span>
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ background: "#F3F5F8", overflow: "hidden", fontFamily: SANS }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * stageScale) / 2, top: (height - 1080 * stageScale) / 2, transform: "scale(" + stageScale + ")", transformOrigin: "top left", color: INK }}>
        <AbsoluteFill style={{ background: "linear-gradient(150deg, #FFFEF8 0%, #F3F5F8 36%, #E4EEFF 75%, #FAFCFF 100%)" }} />
        <AbsoluteFill style={{ opacity: 0.26 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ background: "radial-gradient(62% 78% at " + (65 + shotProgress * 3) + "% 29%, rgba(49,94,255,0.15), transparent 72%), radial-gradient(38% 50% at 16% 84%, rgba(0,167,123,0.07), transparent 74%)" }} />
        <div style={{ position: "absolute", left: 116, top: 186, width: 1688, height: 850, borderRadius: 24, background: "rgba(255,255,255,0.46)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.86)", boxShadow: "0 20px 60px rgba(0,102,255,0.12), inset 0 1px 0 rgba(255,255,255,0.95)" }} />

        <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
          <mg.Marker x={1768} y={150} variant="cross" color={BLUE} />
          <mg.Marker x={1742} y={954} variant="cross" color={GREEN} />
          <mg.Marker x={144} y={998} variant="cross" color={BLUE} />
        </div>

        <div style={{ position: "absolute", left: 116, top: 82, fontSize: 23, lineHeight: "28px", fontWeight: 600, letterSpacing: 3.4, color: BLUE, zIndex: 10 }}>THE REAL ADVANTAGE</div>
        <div style={{ position: "absolute", left: 116, top: 114, fontFamily: "Inter Tight, Inter, Arial, sans-serif", fontWeight: 650, fontSize: 52, lineHeight: "61px", letterSpacing: -1.6, color: INK, whiteSpace: "nowrap", zIndex: 10 }}>A strong record of what happened</div>

        <div style={{ position: "absolute", left: 116, top: 186, width: 1688, height: 850, borderRadius: 24, overflow: "hidden" }}>
          <div style={{ position: "absolute", left: -116, top: -186, width: 1920, height: 1080 }}>
            <mg.CameraRig zoom={zoom} x={rigX} y={rigY}>
              <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080 }}>
                <div style={{ ...glass, left: 180, top: 216, width: 1380, height: 350, transform: "translateY(" + arrivalY + "px)", background: "radial-gradient(100% 150% at 42% 0%, rgba(49,94,255,0.32), transparent 68%), rgba(15,23,42,0.85)" }}>
                  <div style={{ position: "absolute", left: 70, top: 28, fontSize: 27, fontWeight: 650, letterSpacing: 1.6, color: WHITE }}>RECORDED HISTORY</div>
