                </div>

                <div style={{ position: "absolute", inset: 0, transform: "translateY(" + arrivalY + "px)" }}>
                  {[454, 694, 934, 1174].map((x, i) => (
                    <div key={x} style={{ position: "absolute", left: x, top: 397, width: 36, height: 8, borderRadius: 24, background: "#7395FF", opacity: 0.38 + 0.62 * seal, boxShadow: "0 0 18px rgba(49,94,255,0.48)" }}>
                      <div style={{ position: "absolute", left: ((frame * 0.65 + i * 9) % 30), top: 1, width: 6, height: 6, borderRadius: 9999, background: "#D7E5FF", opacity: frame >= blockchainAt ? 0.95 : 0.3 }} />
                    </div>
                  ))}
                  {[
                    { id: "REC-01", hash: "12D8" },
                    { id: "REC-02", hash: "4B7E" },
                    { id: "REC-03", hash: "6C3A" },
                    { id: "REC-04", hash: "8E20" },
