type WordCue = { index?: number; wordIndex?: number; globalIndex?: number; id?: string | number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = { blue: "#315EFF", electric: "#0066FF", coral: "#F36B59", emerald: "#00A77B", amber: "#E8AD36", ink: "#17233B", slate: "#64748B", white: "#F8FAFC" };
