export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const wordAt = (index: number, fallback: number) => {
    const match = cues.find((cue) => cue.wordIndex === index || cue.index === index || cue.globalIndex === index || cue.id === index || cue.id === `W${index}`);
    if (match && Number.isFinite(match.startFrame)) return Math.max(0, match.startFrame as number);
    const positional = cues.length === 17 ? cues[index - 105] : undefined;
    return positional && Number.isFinite(positional.startFrame) ? Math.max(0, positional.startFrame as number) : fallback;
  };
  const tBut = wordAt(105, 0);
  const tHeres = wordAt(106, 2);
  const tProblem = wordAt(108, 20);
  const tAn = wordAt(109, 88);
  const tElection = wordAt(110, 96);
  const tIsnt = wordAt(111, 128);
  const tJust = wordAt(112, 150);
  const tDatabase = wordAt(114, 178);
  const tImagine = wordAt(116, 286);
  const tI = wordAt(117, 308);
  const tVote = wordAt(118, 322);
  const tFrom = wordAt(119, 336);
  const tMy = wordAt(120, 346);
  const tPhone = wordAt(121, 354);
  const shotEnd = Math.max(373, Math.min(412, durationInFrames - 1));
  const ramp = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { ...clamp, easing: ease });
  const snap = (delay: number) => spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });

  const pullback = ramp(tBut + 6, tProblem + 23);
  const leftTrack = ramp(tAn, tDatabase + 3);
  const phonePush = ramp(tImagine, tVote + 3);
  const followToken = ramp(tFrom + 1, tPhone + 4);
  const settleWide = ramp(tPhone + 4, tPhone + 17);
  const ambient = ramp(tPhone + 18, Math.max(tPhone + 19, shotEnd));
  const initialZoom = 1.18 - 0.13 * pullback;
  const focusedZoom = initialZoom + 0.05 * phonePush;
  const zoom = focusedZoom * (1 - settleWide) + settleWide + 0.015 * ambient;
  const basePanX = -110 * (1 - pullback) + 35 * leftTrack;
  const focusedPanX = basePanX * (1 - phonePush) + 60 * phonePush;
  const panX = focusedPanX * (1 - followToken) * (1 - settleWide);
  const panY = (-20 * (1 - pullback) - 20 * phonePush) * (1 - settleWide);

  const headingOpacity = interpolate(frame, [tHeres, tHeres + 12], [0, 1], clamp);
  const questionOneDelay = tElection;
  const questionTwoDelay = tIsnt;
  const phoneOpacity = 0.26 + 0.74 * ramp(tImagine, tI);
  const phoneActive = ramp(tImagine, tVote);
  const selection = ramp(tVote, tVote + 7);
  const touchOpacity = interpolate(frame, [tVote - 1, tVote + 3, tVote + 9, tVote + 19], [0, 0.9, 0.65, 0], clamp);
  const touchRadius = interpolate(frame, [tVote, tVote + 19], [19, 43], clamp);
  const launchAt = tFrom + 1;
  const arriveAt = tPhone + 4;
  const flight = ramp(launchAt, arriveAt);
  const tokenOpacity = interpolate(frame, [launchAt, launchAt + 4], [0, 1], clamp);
  const tokenX = 775 + 500 * flight;
  const arrival = ramp(arriveAt, tPhone + 17);
  const ledgerPulse = Math.max(0, 1 - Math.abs(frame - tDatabase - 6) / 20);
  const markerOpacity = 0.3 + 0.3 * pullback;
