        <AbsoluteFill style={{ background: `radial-gradient(55% 66% at ${72 - 5 * pullback}% 56%, rgba(49,94,255,0.13), transparent 74%), radial-gradient(40% 42% at 30% 24%, rgba(243,107,89,0.10), transparent 75%), radial-gradient(56% 40% at 46% 100%, rgba(255,255,255,0.97), transparent 80%)` }} />
        <div style={{ position: "absolute", left: 248, top: 831, width: 1430, height: 110, borderRadius: 9999, background: "radial-gradient(ellipse, rgba(49,94,255,0.065) 0%, transparent 70%)", filter: "blur(24px)" }} />

