            <span>DOCUMENTARY DOSSIER</span>
            <span style={{ color: C.coral, marginLeft: 9 }}>06 / TRUST BOUNDARIES</span>
          </div>
          <div style={{ position: "absolute", left: 0, top: 38, width: 1400, fontFamily: FONT, fontSize: 54, lineHeight: "64px", fontWeight: 600, letterSpacing: "-0.04em", whiteSpace: "nowrap" }}>An election is more than a database.</div>
        </div>
