  const cues = props.wordCues || [];
  const cue = (index: number, word: string) =>
    cues.find((c) => c.wordIndex === index || c.index === index) ||
    cues.find((c) => normalize(c.word || c.text || "") === normalize(word));
  const start = (index: number, word: string, fallback: number) => cue(index, word)?.startFrame ?? fallback;
  const end = (index: number, word: string, fallback: number) => {
    const c = cue(index, word);
    return c?.spokenEndFrame ?? c?.endFrame ?? fallback;
  };
  const progress = (at: number, until: number) =>
    interpolate(frame, [at, Math.max(at + 1, until)], [0, 1], { ...clamp, easing: ease });
  const settle = (at: number, until: number) => {
    if (frame < at) return 0;
    if (frame >= until) return 1;
    return Math.max(0, Math.min(1, spring({
      frame: frame - at,
      fps,
      config: { damping: 14, stiffness: 160, mass: 0.8 },
    })));
  };

  const nameAt = start(129, "Vaskas", 139);
  const nameEnd = end(129, "Vaskas", 175);
  const idAt = start(134, "ID", 261);
  const idEnd = end(135, "card", 293);
