  const faceEnd = end(139, "recognition", 468);
  const governmentAt = start(142, "government", 513);
  const identityEnd = end(145, "identity", 600);
  const pullAt = identityEnd + 1;
  const pullEnd = Math.max(pullAt + 1, Math.min(identityEnd + 32, durationInFrames - 21));

  const early = progress(start(122, "How", 0), end(128, "actually", 115));
  const selectorMove = progress(start(130, "You", 224), idEnd);
  const bioMove = progress(bioAt, bioEnd);
  const faceMove = progress(faceAt, faceEnd);
  const governmentMove = progress(governmentAt, identityEnd);
  const pull = progress(pullAt, pullEnd);
  const zoom = (1.08 + 0.04 * early - 0.04 * selectorMove - 0.014 * bioMove - 0.013 * faceMove - 0.013 * governmentMove) * (1 - pull) + pull;
