import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type Cue = { wordIndex?: number; globalWordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: Cue[]; recordTokenId?: string; previousRecordTokenId?: string; tokenId?: string };
type Point = { x: number; y: number };
type Curve = [Point, Point, Point, Point];

const C = { ink: '#17233B', slate: '#64748B', blue: '#0066FF', record: '#315EFF', violet: '#8B5CF6', coral: '#FF5A36', paper: '#F3F5F8', white: '#F8FAFC' };
const sans = 'Inter Tight, Inter, Arial, sans-serif';
const mono = 'IBM Plex Mono, SFMono-Regular, Consolas, monospace';
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const ease = Easing.inOut(Easing.cubic);
const ramp = (f: number, a: number, b: number) => interpolate(f, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
const pointOn = (c: Curve, t: number): Point => {
  const u = 1 - t;
  return { x: u * u * u * c[0].x + 3 * u * u * t * c[1].x + 3 * u * t * t * c[2].x + t * t * t * c[3].x, y: u * u * u * c[0].y + 3 * u * u * t * c[1].y + 3 * u * t * t * c[2].y + t * t * t * c[3].y };
};
const curvePath = (c: Curve) => `M ${c[0].x} ${c[0].y} C ${c[1].x} ${c[1].y} ${c[2].x} ${c[2].y} ${c[3].x} ${c[3].y}`;

const CurvedEdge = ({ curve, color, opacity = 1 }: { curve: Curve; color: string; opacity?: number }) => (
  <g opacity={opacity}>
    <path d={curvePath(curve)} fill="none" stroke={color} strokeWidth={8} opacity={0.09} strokeLinecap="round" filter="url(#mgSoft)" />
    <path d={curvePath(curve)} fill="none" stroke={color} strokeWidth={2.6} opacity={0.62} strokeLinecap="round" />
  </g>
);

const GlassNode = ({ x, y, w, h, label, sublabel, accent, opacity = 1, lift = 0, children }: { x: number; y: number; w: number; h: number; label: string; sublabel?: string; accent: string; opacity?: number; lift?: number; children?: React.ReactNode }) => (
  <div style={{ position: 'absolute', left: x, top: y, width: w, height: h, boxSizing: 'border-box', borderRadius: 24, background: 'rgba(15,23,42,0.85)', backdropFilter: 'blur(14px)', border: '1px solid rgba(255,255,255,0.10)', boxShadow: `0 20px 60px ${accent}40, 0 8px 24px rgba(0,0,0,0.22)`, opacity, transform: `translateY(${lift}px)`, overflow: 'hidden', color: C.white }}>
    <div style={{ position: 'absolute', inset: 0, borderRadius: 24, background: `radial-gradient(110% 100% at 20% 0%, ${accent}26, transparent 70%)`, pointerEvents: 'none' }} />
    <div style={{ position: 'absolute', left: 20, top: 17, width: 24, height: 4, background: accent, borderRadius: 9999, boxShadow: `0 0 14px ${accent}66` }} />
    <div style={{ position: 'absolute', left: 20, right: 14, top: 35, fontFamily: sans, fontWeight: 600, fontSize: 26, lineHeight: '30px', letterSpacing: '-0.65px', whiteSpace: 'nowrap' }}>{label}</div>
    {sublabel ? <div style={{ position: 'absolute', left: 21, right: 15, top: 76, fontFamily: mono, fontWeight: 500, fontSize: 12, letterSpacing: '1.15px', color: '#CDD6E7', whiteSpace: 'nowrap' }}>{sublabel}</div> : null}
    {children}
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const fallback = [0, 7, 30, 44, 66, 71, 110, 133, 199, 207, 228, 238, 246, 262, 272, 286, 306, 326, 336, 343, 366];
  const words = ['but', 'now', 'weve', 'created', 'a', 'completely', 'different', 'problem', 'the', 'system', 'has', 'to', 'connect', 'a', 'real', 'human', 'being', 'to', 'a', 'digital', 'vote'];
  const clean = (v: string) => v.toLowerCase().replace(/[^a-z]/g, '');
  const at = (index: number) => {
    const local = index - 146;
    const byIndex = cues.find((c) => c.wordIndex === index || c.globalWordIndex === index || c.index === index);
    const positional = cues.length === 21 ? cues[local] : undefined;
    const named = cues.find((c) => clean(c.word || c.text || '') === words[local] && Math.abs((c.startFrame ?? -1000) - fallback[local]) < 45);
    const value = (byIndex || positional || named)?.startFrame;
    return typeof value === 'number' && value >= 0 && value < durationInFrames ? value : fallback[local];
  };
  const nowAt = at(147);
  const createdAt = at(149);
  const completelyAt = at(151);
  const differentAt = at(152);
  const problemAt = at(153);
  const systemAt = at(155);
  const connectAt = at(158);
  const realAt = at(160);
