import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  wordIndex?: number;
  index?: number;
  id?: string | number;
  startFrame?: number;
  endFrame?: number;
};

type ShotProps = {
  wordCues?: WordCue[];
  recordId?: string;
};

const BLUE = "#0066FF";
const EMERALD = "#10B981";
const AMBER = "#E8AD36";
const WHITE = "#F8FAFC";
const SANS = "Inter, Arial, sans-serif";
const DISPLAY = "Inter Tight, Inter, Arial, sans-serif";
const MONO = "IBM Plex Mono, monospace";
const CENTERS = [420, 780, 1140, 1500];
const LABELS = ["TX-A", "TX-B", "TX-C", "TX-D"];
const ease = Easing.inOut(Easing.cubic);
const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(max, value));
const mix = (value: number, from: number, to: number, a: number, b: number) => interpolate(value, [from, Math.max(from + 1, to)], [a, b], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueStart = (index: number, fallback: number) => {
    const found = cues.find((cue) => cue.wordIndex === index || cue.index === index || String(cue.id) === "W" + index || String(cue.id) === String(index));
    return typeof found?.startFrame === "number" ? found.startFrame : fallback;
  };
  const blockchainAt = cueStart(213, 8);
  const fundamentalAt = cueStart(215, 55);
  const designedAt = cueStart(216, 95);
  const aroundAt = cueStart(217, 124);
  const creatingAt = cueStart(218, 144);
  const articleAt = cueStart(219, 170);
  const permanentAt = cueStart(220, 189);
  const verifiableAt = cueStart(221, 238);
  const recordAt = cueStart(222, 281);
  const ofAt = cueStart(223, 304);
  const transactionsAt = cueStart(224, 309);
  const forwardEnd = articleAt + 11;
  const focusEnd = permanentAt + 34;
  const returnEnd = verifiableAt + 46;
  const pullbackEnd = transactionsAt + 32;
  const lastFrame = Math.max(pullbackEnd + 1, durationInFrames - 1);
  const recordId = props.recordId || "REC-01";

  let zoom = 1.15;
  let panX = 60;
  let panY = 10;
  if (frame >= blockchainAt) {
    zoom = mix(frame, blockchainAt, blockchainAt + 38, 1.15, 1.20);
    panX = mix(frame, blockchainAt, blockchainAt + 38, 60, 70);
  }
  if (frame >= blockchainAt + 38) {
    zoom = mix(frame, blockchainAt + 38, forwardEnd, 1.20, 1.10);
    panX = mix(frame, blockchainAt + 38, forwardEnd, 70, -30);
    panY = mix(frame, blockchainAt + 38, forwardEnd, 10, 0);
  }
  if (frame >= permanentAt) {
    zoom = mix(frame, permanentAt, focusEnd, 1.10, 1.14);
    panX = mix(frame, permanentAt, focusEnd, -30, 50);
    panY = 0;
  }
  if (frame >= recordAt) {
    zoom = mix(frame, recordAt, pullbackEnd, 1.14, 1);
    panX = mix(frame, recordAt, pullbackEnd, 50, 0);
    panY = 0;
  }
  if (frame >= pullbackEnd) {
    zoom = mix(frame, pullbackEnd, lastFrame, 1, 1.015);
    panX = 0;
    panY = 0;
  }

  // The rig's centered transform is corrected to pivot at design-space (960, 590).
  // Include the panel spring envelope and qualification-strip corners in the per-frame audit.
  const safetyEnvelope = { left: 301, right: 1619, top: 260, bottom: 969 };
  const transformedX = (x: number) => 960 + (x - 960) * zoom;
  const transformedY = (y: number) => 590 + (y - 590) * zoom;
  panX = clamp(panX, 100 - transformedX(safetyEnvelope.left), 1820 - transformedX(safetyEnvelope.right));
  panY = clamp(panY, 205 - transformedY(safetyEnvelope.top), 1000 - transformedY(safetyEnvelope.bottom));
  const rigY = panY + (590 - 540) * (1 - zoom);

  let cursorX = 420;
  if (frame >= fundamentalAt) cursorX = mix(frame, fundamentalAt, designedAt, 420, 780);
  if (frame >= aroundAt) cursorX = mix(frame, aroundAt, creatingAt, 780, 1140);
  if (frame >= creatingAt + 5) cursorX = mix(frame, creatingAt + 5, forwardEnd, 1140, 1500);
  if (frame >= verifiableAt) cursorX = mix(frame, verifiableAt, returnEnd, 1500, 420);

  let forwardHead = 420;
  if (frame >= fundamentalAt) forwardHead = mix(frame, fundamentalAt, designedAt, 420, 780);
  if (frame >= aroundAt) forwardHead = mix(frame, aroundAt, creatingAt, 780, 1140);
  if (frame >= creatingAt + 5) forwardHead = mix(frame, creatingAt + 5, forwardEnd, 1140, 1500);

  const arrivals = [26, designedAt, creatingAt, forwardEnd];
  const arrivalDelays = [2, fundamentalAt, aroundAt, creatingAt + 5];
  const returning = frame >= verifiableAt && frame < returnEnd;
  const checking = frame >= returnEnd;
  const checkProgress = mix(frame, returnEnd, returnEnd + 14, 0, 1);
  const storedCount = arrivals.reduce((count, at) => count + (frame >= at ? 1 : 0), 0);
  const completeProgress = mix(frame, ofAt, transactionsAt + 10, 0, 1);
  const packetX = clamp(cursorX + (returning ? -34 : 34), 420, 1500);
  const packetOpacity = frame >= 26 && frame < returnEnd ? 0.55 + 0.3 * Math.sin(frame * 0.15) ** 2 : 0;
  const shellSpring = spring({ frame: Math.max(0, frame - 2), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const scale = Math.min(width / 1920, height / 1080);
  const guideOpacity = mix(frame, 2, 20, 0, 1);

  return (
    <AbsoluteFill style={{ background: "#070A12", overflow: "hidden", color: WHITE, fontFamily: SANS }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * scale) / 2, top: (height - 1080 * scale) / 2, transform: "scale(" + scale + ")", transformOrigin: "0 0" }}>
        <AbsoluteFill style={{ background: "linear-gradient(155deg, #070A12 0%, #10192B 46%, #0C1830 76%, #070A12 100%)" }} />
        <AbsoluteFill style={{ opacity: 0.2 }}>
          <mg.GridBackground mode="dark" gridSize={48} />
        </AbsoluteFill>
        <AbsoluteFill style={{ background: "radial-gradient(65% 80% at " + (38 + frame * 0.025) + "% 35%, rgba(0,102,255,0.20), transparent 72%), radial-gradient(40% 44% at 85% 86%, rgba(16,185,129,0.065), transparent 75%)" }} />

        <div style={{ position: "absolute", inset: "180px 0 0 0", overflow: "hidden", borderRadius: 28 }}>
          <div style={{ position: "absolute", top: -180, left: 0, width: 1920, height: 1080 }}>
            <mg.CameraRig zoom={zoom} x={panX} y={rigY}>
              <div style={{ position: "absolute", inset: 0 }}>
                <div style={{ position: "absolute", left: 115, top: 180, width: 1690, height: 850, boxSizing: "border-box", borderRadius: 28, background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxShadow: "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.4)", overflow: "hidden" }}>
                  <AbsoluteFill style={{ borderRadius: 28, background: "radial-gradient(75% 75% at 35% 10%, rgba(0,102,255,0.11), transparent 75%), linear-gradient(180deg, rgba(255,255,255,0.018), transparent 40%)" }} />
                  <div style={{ position: "absolute", left: 124, right: 124, top: 685, height: 1, borderRadius: 9999, background: "linear-gradient(90deg, transparent, rgba(59,130,246,0.22), transparent)" }} />
                </div>

                <div style={{ opacity: guideOpacity }}>
                  <mg.Marker x={270} y={320} variant="cross" color="#0066FF" />
                  <mg.Marker x={1650} y={320} variant="cross" color="#3B82F6" />
                  <mg.Marker x={1660} y={865} variant="cross" color="#E8AD36" />
                </div>

                <div style={{ position: "absolute", left: 340, top: 266, width: 570, opacity: guideOpacity }}>
                  <div style={{ fontSize: 16, fontWeight: 600, letterSpacing: 3, color: "#83B6FF" }}>ACCUMULATING TRANSACTION HISTORY</div>
                  <div style={{ marginTop: 11, fontSize: 25, lineHeight: 1.2, fontFamily: DISPLAY, fontWeight: 600 }}>Earlier entries stay available.</div>
                </div>
                <div style={{ position: "absolute", right: 340, top: 270, display: "flex", alignItems: "center", gap: 10, padding: "10px 15px", borderRadius: 9999, border: "1px solid rgba(59,130,246,0.32)", background: "rgba(0,102,255,0.09)", color: "#B9D7FF", fontFamily: MONO, fontSize: 16, fontWeight: 500, fontVariantNumeric: "tabular-nums", opacity: guideOpacity }}>
                  <span style={{ width: 7, height: 7, borderRadius: 9999, background: BLUE, boxShadow: "0 0 12px rgba(0,102,255,0.65)" }} />
                  {String(storedCount).padStart(2, "0")} / 04 RETAINED
                </div>

                <svg width={1920} height={1080} viewBox="0 0 1920 1080" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
                  <defs>
                    <filter id="mgGlow" x="-100%" y="-100%" width="300%" height="300%">
                      <feGaussianBlur stdDeviation="4" result="blur" />
                      <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
                    </filter>
                    <filter id="mgSoft" x="-100%" y="-100%" width="300%" height="300%">
                      <feGaussianBlur stdDeviation="9" />
                    </filter>
                    <linearGradient id="historyRail" x1="235" y1="800" x2="1685" y2="800" gradientUnits="userSpaceOnUse">
                      <stop offset="0" stopColor="#0066FF" stopOpacity="0.2" />
                      <stop offset="0.5" stopColor="#3B82F6" stopOpacity="0.5" />
                      <stop offset="1" stopColor="#0066FF" stopOpacity="0.2" />
                    </linearGradient>
                  </defs>
                  <path d="M235 800 H1685" stroke="url(#historyRail)" strokeWidth={4} strokeLinecap="round" fill="none" />
                  <path d={"M235 800 H" + forwardHead} stroke={BLUE} strokeWidth={13} strokeLinecap="round" opacity={0.38 * guideOpacity} filter="url(#mgSoft)" fill="none" />
                  <path d={"M235 800 H" + forwardHead} stroke="#3B82F6" strokeWidth={5} strokeLinecap="round" opacity={guideOpacity} fill="none" />
                  {CENTERS.map((x, i) => (
                    <path key={"link-" + i} d={"M" + x + " 492 V530"} stroke={frame >= arrivals[i] ? "#3B82F6" : "#203653"} strokeWidth={2} strokeLinecap="round" strokeDasharray="3 7" opacity={frame >= arrivals[i] ? 0.6 : 0.2} />
                  ))}
                </svg>

                {CENTERS.map((x, i) => {
                  const inspected = frame >= arrivals[i];
                  const enter = frame < arrivalDelays[i] ? 0 : spring({ frame: frame - arrivalDelays[i], fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
                  const panelSpring = frame < arrivals[i] ? 0 : spring({ frame: frame - arrivals[i], fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
                  const panelScale = clamp(0.96 + panelSpring * 0.04, 0.96, 1.02);
                  const isActive = Math.abs(cursorX - x) < 85 && frame >= 20;
                  const isChecked = i === 0 && checking;
                  const dormant = 1 - clamp(enter, 0, 1);
                  return (
                    <React.Fragment key={LABELS[i]}>
                      <div style={{ position: "absolute", left: x - 80, top: 530, width: 160, height: 270, boxSizing: "border-box", overflow: "hidden", borderRadius: 24, border: "1px solid rgba(69,147,255," + (0.16 + 0.45 * clamp(enter, 0, 1)) + ")", background: "linear-gradient(165deg, rgba(0,102,255," + (0.04 + 0.32 * clamp(enter, 0, 1)) + "), rgba(0,62,177," + (0.03 + 0.13 * clamp(enter, 0, 1)) + "))", boxShadow: dormant > 0.99 ? "0 20px 60px rgba(0,102,255,0.07), 0 8px 24px rgba(0,0,0,0.25)" : "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.4)" }}>
                        <div style={{ position: "absolute", inset: 0, borderRadius: 24, opacity: isActive ? 0.28 : 0.10, background: "radial-gradient(120% 85% at 50% 0%, #3B82F6, transparent 85%)" }} />
                        <div style={{ position: "absolute", left: 20, top: 18, width: 38, height: 4, borderRadius: 9999, background: "#3B82F6", opacity: 0.18 + 0.72 * clamp(enter, 0, 1) }} />
                        <div style={{ position: "absolute", left: 0, right: 0, bottom: 55, textAlign: "center", fontFamily: MONO, fontSize: 30, fontWeight: 500, color: inspected ? WHITE : "#8DB5F0", opacity: 0.4 + 0.6 * clamp(enter, 0, 1) }}>{LABELS[i]}</div>
                        <div style={{ position: "absolute", left: 0, right: 0, bottom: 28, textAlign: "center", fontSize: 12, fontWeight: 600, letterSpacing: 2, color: "#B6D4FF", opacity: inspected ? 0.9 : 0.25 }}>{inspected ? "STORED ENTRY" : "ENTRY SLOT"}</div>
                        {i > 0 && (
                          <div style={{ position: "absolute", left: 38, top: 70, width: 84, height: 66, borderRadius: 22, border: "1px solid rgba(104,167,255,0.3)", background: "rgba(0,102,255,0.14)", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", gap: 9, opacity: clamp(enter, 0, 1) }}>
