export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.max(0, Math.min(frame, durationInFrames - 1));
  const cueAt = (index: number) => {
    const supplied = cues.find((cue) => cue.wordIndex === index || cue.index === index || cue.id === index || cue.id === `W${index}`);
    const positional = cues.length === FALLBACK_CUES.length ? cues[index - 225] : undefined;
    return supplied?.startFrame ?? positional?.startFrame ?? FALLBACK_CUES.find((entry) => entry[0] === index)?.[1] ?? 0;
  };
  const proveAt = cueAt(230);
  const personAt = cueAt(233);
  const castAt = cueAt(235);
  const voteAt = cueAt(237);
  const togetherAt = cueAt(240);
  const sureAt = cueAt(242);
  const nobodyAt = cueAt(243);
  const whichVoteAt = cueAt(248);
  const belongsAt = cueAt(249);
  const finalPersonAt = cueAt(252);
