  const returnAt = concealEnd + 1;
  const returnEnd = returnAt + 32;
  const ramp = (start: number, end: number, from = 0, to = 1) => interpolate(f, [start, end], [from, to], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic),
  });
  const reveal = (start: number) => Math.min(1, Math.max(0, spring({
    frame: f - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 },
  })));
  const prove = reveal(proveAt);
  const personFocus = ramp(personAt, personAt + 22) * (1 - 0.65 * ramp(castAt, voteAt));
  const voteFocus = ramp(voteAt, voteAt + 25) * (1 - 0.65 * ramp(togetherAt, togetherEnd));
