import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from 'remotion';
import { mg } from '@frame60/mg';

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[]; recordId?: string; inheritedRecordId?: string };
type ModuleSpec = { id: string; label: string; x: number; y: number; at: number; accent: string; descriptor: string; plane: number };
type LinkSpec = { id: string; d: string; at: number; blue: boolean; packets: boolean };

const INK = '#17233B';
const BLUE = '#0066FF';
const RECORD_BLUE = '#315EFF';
const VIOLET = '#8B5CF6';
const CORAL = '#F36B59';
const AMBER = '#E8AD36';
const FONT = 'Inter Tight, Inter, Arial, sans-serif';
const MONO = 'IBM Plex Mono, monospace';
const ease = Easing.inOut(Easing.cubic);
const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const phase = (frame: number, start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number) => {
    const explicit = cues.find((item) => item.wordIndex === index || item.index === index);
    const local = cues.length === 23 ? cues[index - 267] : undefined;
    const match = explicit || local;
    return typeof match?.startFrame === 'number' ? match.startFrame : fallback;
  };
  const simpleAt = cue(270, 46);
  const onlineAt = cue(271, 66);
  const votingAt = cue(272, 90);
  const openingSystemAt = cue(273, 110);
  const liftAt = cue(274, 145);
  const becomeAt = cue(275, 159);
  const extremeAt = cue(277, 189);
  const complexAt = cue(278, 228);
  const cryptoAt = cue(279, 272);
  const meshAt = cue(280, 312);
  const workAt = cue(284, 382);
  const flawlessAt = cue(285, 395);
  const millionsAt = cue(287, 459);
  const peopleAt = cue(289, 488);
  const finalFrame = Math.min(551, durationInFrames - 1);
  const recordId = props.inheritedRecordId || props.recordId || 'REC-014';
  const reveal = (start: number, length = 22) => {
    if (frame < start) return 0;
    const physical = spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
    return clamp01(physical) * phase(frame, start, start + Math.min(length, 10));
  };

  const closeMove = phase(frame, 0, 135);
  const pushMove = phase(frame, liftAt, 230);
  const wideMove = phase(frame, complexAt, 337);
  const drift = phase(frame, 337, 435);
  const finalMove = phase(frame, millionsAt, 485);
  const settle = phase(frame, 510, Math.max(511, finalFrame));
  let zoom = mix(1.15, 1.18, closeMove);
  let panX = 0;
  if (frame >= liftAt) zoom = mix(1.18, 1.2, pushMove);
  if (frame >= complexAt) {
    zoom = mix(1.2, 1.04, wideMove);
    panX = mix(0, -35, wideMove);
  }
  if (frame >= 337) {
    zoom = mix(1.04, 1.035, drift);
    panX = mix(-35, -27, drift);
  }
  if (frame >= millionsAt) {
    zoom = mix(1.035, 1, finalMove);
    panX = mix(-27, 0, finalMove);
  }
  zoom = Math.min(1.2, Math.max(1, zoom));
