import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[]; recordId?: string; storedRecordId?: string };

const C = { white: "#F8FAFC", blue: "#0066FF", record: "#315EFF", coral: "#FF5A36", amber: "#E8AD36", ink: "#10192B", muted: "#AEBFD8" };
const sans = '"Inter Tight", "Inter", sans-serif';
const mono = '"IBM Plex Mono", monospace';
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const ease = Easing.bezier(0.4, 0, 0.2, 1);
const cueIndices = [317, 318, 319, 320, 321, 322, 323, 324, 325, 326, 327, 328, 329, 330, 331, 332, 333, 334, 335, 336, 337, 338, 339, 340, 341];
const cueDefaults = [0, 48, 58, 68, 82, 94, 134, 156, 183, 206, 217, 241, 260, 268, 276, 343, 355, 362, 370, 441, 457, 523, 544, 552, 561];
const cueWords = ["but", "if", "you", "vote", "from", "home", "what's", "stopping", "someone", "from", "standing", "behind", "you", "and", "saying", "vote", "for", "this", "candidate", "or", "worse", "show", "me", "your", "screen"];
const normalize = (s: string) => s.toLowerCase().replace(/[.,?!:;’]/g, "").trim();
const phase = (frame: number, start: number, length: number) => interpolate(frame, [start, start + length], [0, 1], { ...clamp, easing: ease });

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.max(0, Math.min(frame, durationInFrames - 1));
  const scale = Math.min(width / 1920, height / 1080);
  const at = (index: number) => {
    const local = cueIndices.indexOf(index);
    const fallback = cueDefaults[local] ?? 0;
    const explicit = cues.find((c) => c.wordIndex === index || c.index === index);
    const positional = cues.length === 25 ? cues[local] : undefined;
    const textual = cues.find((c) => normalize(c.word || c.text || "") === cueWords[local] && typeof c.startFrame === "number" && Math.abs(c.startFrame - fallback) < 30);
    const cue = explicit || positional || textual;
    return typeof cue?.startFrame === "number" && cue.startFrame >= 0 && cue.startFrame < durationInFrames ? cue.startFrame : fallback;
  };
  const homeAt = at(322);
  const someoneAt = at(325);
  const standingAt = at(327);
  const behindAt = at(328);
  const sayingAt = at(331);
  const voteAt = at(332);
  const candidateAt = at(335);
  const orAt = at(336);
  const worseAt = at(337);
  const showAt = at(338);
  const screenAt = at(341);

  const moves = [
    { start: homeAt, end: homeAt + 20, z: 1.04, x: 10, y: -5 },
    { start: someoneAt, end: behindAt + 22, z: 1.10, x: 55, y: -20 },
    { start: sayingAt, end: sayingAt + 21, z: 1.16, x: -35, y: 0 },
    { start: voteAt, end: candidateAt + 26, z: 1.22, x: -70, y: 10 },
    { start: orAt, end: worseAt + 25, z: 1.15, x: -35, y: 0 },
    { start: showAt, end: screenAt + 28, z: 1.0, x: 0, y: 0 },
  ];
  let zoom = 1;
  let camX = 0;
  let camY = 0;
  for (const m of moves) {
    const t = phase(f, m.start, Math.max(1, m.end - m.start));
    zoom += (m.z - zoom) * t;
    camX += (m.x - camX) * t;
    camY += (m.y - camY) * t;
  }
  const snappy = (start: number) => f < start ? 0 : spring({ frame: f - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const sceneIn = phase(f, 0, 20);
  const homeIn = phase(f, homeAt, 20);
  const observerIn = phase(f, someoneAt, 14);
  const observerSpring = snappy(someoneAt);
  const observerSettled = 1 - phase(f, behindAt, 22);
  const directionIn = phase(f, voteAt, 14);
  const directionSpring = snappy(voteAt);
  const directionFade = 1 - phase(f, orAt, 34);
  const accessIn = phase(f, orAt, Math.max(1, worseAt + 25 - orAt));
  const accessFull = phase(f, showAt, Math.max(1, screenAt + 28 - showAt));
  const accessOutline = phase(f, showAt, 18);
  const sightDraw = phase(f, standingAt, Math.max(1, behindAt + 22 - standingAt));
  const scan = phase(f, showAt, Math.max(1, screenAt + 28 - showAt));
  const recordId = String(props.recordId || props.storedRecordId || "R-0417");

  const source = { x: 650, y: 800 };
  const rightX = 1058 + (1246 - 1058) * accessFull;
  const rightY = 402 + (344 - 402) * accessFull;
  const leftX = 907 + (864 - 907) * accessFull;
  const leftY = 488 + (556 - 488) * accessFull;
  const r = 25;
  const endpoint = (x: number, y: number) => {
    const distance = Math.hypot(x - source.x, y - source.y);
    return { x: source.x + (x - source.x) * r / distance, y: source.y + (y - source.y) * r / distance };
  };
  const rightStart = endpoint(rightX, rightY);
  const leftStart = endpoint(leftX, leftY);
  const wedgePath = accessFull > 0.0001
    ? `M ${rightStart.x} ${rightStart.y} L ${rightX} ${rightY} L ${rightX} ${leftY} Q ${rightX} ${leftY + 1} ${rightX - 1} ${leftY + 1} L ${leftX} ${leftY} L ${leftStart.x} ${leftStart.y} Z`
    : `M ${rightStart.x} ${rightStart.y} L ${rightX} ${rightY} L ${leftX} ${leftY} L ${leftStart.x} ${leftStart.y} Z`;
