import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; startFrame?: number; text?: string; word?: string };
type ShotProps = {
  wordCues?: WordCue[];
  recordId?: string;
  inheritedRecordId?: string;
  previousShot?: { recordId?: string };
  previousShotState?: { recordId?: string };
};

const P = {
  ink: "#17233B",
  slate: "#64748B",
  blue: "#315EFF",
  emerald: "#00A77B",
  coral: "#F36B59",
  amber: "#E8AD36",
};
const UI = "'Inter', 'Arial', sans-serif";
const TITLE = "'Inter Tight', 'Inter', 'Arial', sans-serif";
const MONO = "'IBM Plex Mono', 'SFMono-Regular', monospace";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const ease = Easing.inOut(Easing.cubic);
const mix = (f: number, a: number, b: number, from: number, to: number) => interpolate(f, [a, b], [from, to], { ...clamp, easing: ease });
const rgba = (hex: string, alpha: number) => {
  const value = parseInt(hex.replace("#", ""), 16);
  return `rgba(${(value >> 16) & 255},${(value >> 8) & 255},${value & 255},${alpha})`;
};
const glow = (color: string, opacity = 0.15) => `0 20px 60px ${rgba(color, opacity)}, 0 8px 24px rgba(23,35,59,0.08)`;
const whiteGlass = (color: string): React.CSSProperties => ({
  position: "absolute",
  borderRadius: 24,
  background: "linear-gradient(145deg, rgba(255,255,255,0.91), rgba(255,255,255,0.76))",
  backdropFilter: "blur(14px)",
  border: "1px solid rgba(23,35,59,0.09)",
  boxShadow: glow(color),
  boxSizing: "border-box",
});

const Check = ({ color, size = 18 }: { color: string; size?: number }) => (
  <span style={{ width: size, height: size, display: "inline-flex", position: "relative", flexShrink: 0 }}>
    <span style={{ position: "absolute", width: size * 0.37, height: size * 0.69, left: size * 0.29, top: size * 0.01, borderRight: `3px solid ${color}`, borderBottom: `3px solid ${color}`, borderRadius: 2, transform: "rotate(43deg)" }} />
  </span>
);

// HTML-only functional routing: no illustrative SVG or inferred voting data.
const DashRoute = ({ progress, opacity, phase }: { progress: number; opacity: number; phase: number }) => {
  const segments: Array<{ x: number; y: number; w: number; h: number }> = [];
  for (let y = 393; y <= 443; y += 18) segments.push({ x: 1124, y, w: 4, h: 10 });
  for (let x = 1136; x <= 1334; x += 18) segments.push({ x, y: 449, w: 10, h: 4 });
  for (let y = 459; y <= 549; y += 18) segments.push({ x: 1347, y, w: 4, h: 10 });
  return (
    <div style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}>
      {segments.map((d, i) => {
        const reveal = interpolate(progress, [i / segments.length, (i + 1) / segments.length], [0, 1], clamp);
        const active = Math.max(0, 1 - Math.abs(i / segments.length - phase) * 8);
        return <div key={i} style={{ position: "absolute", left: d.x, top: d.y, width: d.w, height: d.h, borderRadius: 9999, background: P.amber, opacity: reveal * (0.67 + active * 0.33), boxShadow: `0 0 ${5 + active * 6}px ${rgba(P.amber, 0.24 + active * 0.23)}` }} />;
      })}
      <div style={{ position: "absolute", left: 1342, top: 547, width: 14, height: 14, borderRadius: 9999, border: `3px solid ${P.amber}`, background: "#FFF7E6", boxSizing: "border-box", opacity: interpolate(progress, [0.88, 1], [0, 1], clamp), boxShadow: glow(P.amber, 0.22) }} />
    </div>
  );
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number, word: string) => {
    const found = cues.find(c => (c.wordIndex ?? c.index) === index) ?? cues.find(c => (c.word ?? c.text ?? "").toLowerCase().replace(/[^a-z]/g, "") === word);
    return typeof found?.startFrame === "number" ? found.startFrame : fallback;
  };
  const cue = {
    blockchain: cueAt(342, 0, "blockchain"),
    cant: cueAt(343, 22, "cant"),
    solve: cueAt(344, 33, "solve"),
    that: cueAt(345, 47, "that"),
    in: cueAt(346, 101, "in"),
    fact: cueAt(347, 111, "fact"),
    making: cueAt(348, 147, "making"),
    a: cueAt(349, 168, "a"),
    vote: cueAt(350, 174, "vote"),
    digitally: cueAt(351, 189, "digitally"),
    verifiable: cueAt(352, 215, "verifiable"),
    could: cueAt(353, 274, "could"),
    make: cueAt(354, 288, "make"),
    coercion: cueAt(355, 306, "coercion"),
    easier: cueAt(356, 348, "easier"),
  };
  const f = Math.min(frame, durationInFrames - 1);
  const rise = (start: number) => Math.min(1, Math.max(0, spring({ frame: Math.max(0, f - start), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } })));

  // Fixed center-pivot camera: p' = c + (p - c + offset) * zoom.
  // Heading and kicker remain outside this stage transform.
  let zoom = 1.15;
  let panX = 0;
  let panY = 0;
  const focusStart = cue.in;
  const pushStart = cue.digitally + 3;
  const pushEnd = cue.verifiable + 42;
  const pullStart = cue.could;
  const pullEnd = cue.easier + 29;
  if (f <= 25) {
    panX = mix(f, 0, 25, 0, 65);
  } else if (f <= 60) {
    panX = mix(f, 26, 60, 65, -65);
  } else if (f < focusStart) {
    panX = -65;
  } else if (f < pushStart) {
    zoom = mix(f, focusStart, pushStart - 1, 1.15, 1.12);
    panX = mix(f, focusStart, pushStart - 1, -65, 0);
    panY = mix(f, focusStart, pushStart - 1, 0, -20);
  } else if (f < pullStart) {
    zoom = mix(f, pushStart, pushEnd, 1.12, 1.15);
    panY = -20;
  } else {
    zoom = mix(f, pullStart, pullEnd, 1.15, 1);
    panY = mix(f, pullStart, pullEnd, -20, 0);
  }

  // An ID may only come from continuity props. Missing continuity is intentionally blank.
  const inheritedId = props.inheritedRecordId ?? props.previousShotState?.recordId ?? props.previousShot?.recordId ?? props.recordId;
  const recordId = typeof inheritedId === "string" ? inheritedId : "";
  const idSize = recordId.length > 26 ? 13 : recordId.length > 18 ? 16 : 20;

  const scanStart = cue.blockchain;
  const scanEnd = cue.cant + 7;
  const firstScan = interpolate(f, [scanStart, scanEnd], [0, 1], clamp);
  const scanFade = interpolate(f, [scanStart, scanStart + 4, scanEnd - 5, scanEnd + 5], [0, 0.9, 0.9, 0], clamp);
  const secondScan = interpolate(f, [cue.digitally, cue.verifiable + 17], [0, 1], clamp);
  const secondFade = interpolate(f, [cue.digitally, cue.digitally + 5, cue.verifiable + 12, cue.verifiable + 23], [0, 0.85, 0.85, 0], clamp);
  const checkReveal = rise(cue.solve);
  const recordNote = rise(cue.that);
  const headerFocus = interpolate(f, [cue.in, cue.fact + 14], [0, 1], clamp);
  const conditionLineOne = rise(cue.making);
  const conditionLineTwo = rise(cue.vote);
  const conditionBody = rise(cue.a);
  const verificationRefresh = f >= cue.verifiable ? Math.sin(Math.PI * interpolate(f, [cue.verifiable, cue.verifiable + 42], [0, 1], clamp)) : 0;
  const consequenceRise = rise(cue.coercion);
  const easierRise = rise(cue.easier);
  const consequencePulse = f >= cue.easier ? Math.sin(Math.PI * interpolate(f, [cue.easier, cue.easier + 29], [0, 1], clamp)) : 0;
  const routeAlpha = interpolate(f, [cue.could, cue.could + 7], [0, 1], clamp);
