  const endingNote = rise(cue.make);
  const problemAttention = f >= cue.cant ? Math.sin(Math.PI * interpolate(f, [cue.cant, cue.that + 22], [0, 1], clamp)) : 0;
  const blueRunStart = f < cue.digitally ? scanStart : cue.digitally;
  const blueRunEnd = f < cue.digitally ? scanEnd : cue.verifiable + 17;
