};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: string | number; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[]; recordId?: string; inheritedRecordId?: string };

const C = { porcelain: '#F3F5F8', ink: '#17233B', slate: '#64748B', blue: '#315EFF', coral: '#F36B59', amber: '#E8AD36', white: '#F8FAFC' };
const SANS = '"Inter", "Arial", sans-serif';
const TIGHT = '"Inter Tight", "Inter", "Arial", sans-serif';
const MONO = '"IBM Plex Mono", "SFMono-Regular", monospace';
const ease = Easing.bezier(0.4, 0, 0.2, 1);
const clamp = (v: number, min = 0, max = 1) => Math.min(max, Math.max(min, v));
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const glow = '0 20px 60px rgba(49,94,255,0.14), 0 8px 24px rgba(23,35,59,0.09)';

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueFrame = (index: number, fallback: number, word: string) => {
    const byId = cues.find((cue) => cue.wordIndex === index || cue.index === index || String(cue.id) === String(index) || cue.id === 'W' + index);
    const byWord = cues.find((cue) => (cue.word || cue.text || '').toLowerCase().replace(/[^a-z]/g, '') === word);
    const found = byId || byWord;
    return found && typeof found.startFrame === 'number' ? found.startFrame : fallback;
  };
  const cyberAt = cueFrame(360, 72, 'cyber');
  const securityAt = cueFrame(361, 92, 'security');
  const peopleAt = cueFrame(362, 162, 'people');
  const oftenAt = cueFrame(363, 182, 'often');
  const sayAt = cueFrame(364, 198, 'say');
  const blockchainAt = cueFrame(365, 255, 'blockchain');
  const isAt = cueFrame(366, 312, 'is');
  const impossibleAt = cueFrame(367, 321, 'impossible');
  const toAt = cueFrame(368, 358, 'to');
  const hackAt = cueFrame(369, 366, 'hack');
  const thatsAt = cueFrame(370, 424, 'thats');
  const notAt = cueFrame(371, 463, 'not');
  const trueAt = cueFrame(372, 479, 'true');
  const lockAt = Math.max(impossibleAt + 12, toAt + 2);
  const verdictEnd = trueAt + 18;
  const shotEnd = Math.max(verdictEnd + 1, durationInFrames - 1);
  const ramp = (start: number, duration: number) => interpolate(frame, [start, start + duration], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const snap = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const badgeSpring = clamp(snap(peopleAt), 0, 1.035);
  const inputReveal = ramp(cyberAt, 16);
  const attach = ramp(oftenAt, 12);
  const headIn = ramp(2, 20);
  const plateIn = ramp(0, 24);
  const zoom = interpolate(frame, [0, 186, 423, 497, shotEnd], [1.06, 1.15, 1.15, 1, 1.01], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const panX = interpolate(frame, [0, 198, 360, 423, 497, shotEnd], [0, 0, -40, -40, 0, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const panY = interpolate(frame, [0, 186, 198, 360, 423, 497, shotEnd], [0, 20, 20, 0, 0, 0, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });

  // The physical plate remains inside the safe area while the optical interior moves.
  // Insets counter the camera scale, retaining a rounded full plate silhouette.
  const outerW = 1690 / zoom;
  const outerH = 850 / zoom;
  const outerX = (115 - 960 - panX) / zoom + 960;
  const outerY = (150 - 540 - panY) / zoom + 540;
  const scanStart = Math.max(peopleAt + 24, sayAt);
  const scanT = ramp(scanStart, Math.max(1, lockAt - scanStart));
  const contraction = ramp(impossibleAt, Math.max(12, lockAt - impossibleAt));
  const apertureX = mix(36, 553, scanT);
  const apertureW = mix(414, 291, contraction);
  const apertureTop = mix(10, 18, contraction);
  const apertureHeight = mix(100, 84, contraction);
  const focusIn = ramp(lockAt, 12);
  const opticalOpacity = ramp(scanStart, 16) * (1 - focusIn);
  const focusSpring = clamp(snap(lockAt), 0, 1.025);
  const absoluteLabelIn = ramp(lockAt + 4, 12);
  const trayReveal = ramp(thatsAt, 12);
  const traySpring = clamp(snap(thatsAt), 0, 1.018);
  const falseIn = ramp(notAt, 10);
  const qualifierIn = ramp(trueAt, 14);
  const recordAttention = ramp(verdictEnd, Math.max(1, shotEnd - verdictEnd));
  const recordId = props.inheritedRecordId ?? props.recordId ?? '0x7C2A';
  const monoIdSize = recordId.length > 12 ? 16 : 22;

  const quoteWords = [
    { text: 'Blockchain', x: 70, width: 349, start: blockchainAt },
    { text: 'is', x: 448, width: 60, start: isAt },
    { text: 'impossible', x: 568, width: 265, start: impossibleAt },
    { text: 'to', x: 866, width: 60, start: toAt },
    { text: 'hack.', x: 966, width: 154, start: hackAt },
  ];

  return (
    <AbsoluteFill style={{ background: C.porcelain, overflow: 'hidden', fontFamily: SANS, color: C.ink }}>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * Math.min(width / 1920, height / 1080)) / 2, top: (height - 1080 * Math.min(width / 1920, height / 1080)) / 2, transform: 'scale(' + Math.min(width / 1920, height / 1080) + ')', transformOrigin: '0 0' }}>
        {/* 1. Porcelain field. 2. Structural grid. 3. Directional light. */}
        <AbsoluteFill style={{ background: 'linear-gradient(153deg, #FFFFFF 0%, #F3F5F8 35%, #E5ECF9 69%, #F8F3EE 100%)' }} />
        <AbsoluteFill style={{ opacity: 0.34 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ background: 'radial-gradient(58% 74% at 75% 32%, rgba(49,94,255,0.12), transparent 73%), radial-gradient(38% 49% at 16% 80%, rgba(243,107,89,0.10), transparent 74%), radial-gradient(45% 40% at 30% 8%, rgba(255,255,255,0.92), transparent 75%)' }} />

        {/* Fixed editorial heading: outside the stage camera. */}
        <div style={{ position: 'absolute', left: 112, top: 80, height: 64, display: 'flex', alignItems: 'center', gap: 26, opacity: headIn, transform: 'translateY(' + (1 - headIn) * 8 + 'px)', zIndex: 20 }}>
          <div style={{ fontSize: 23, fontWeight: 500, letterSpacing: 2.3, color: C.blue, whiteSpace: 'nowrap' }}>CYBERSECURITY</div>
          <div style={{ width: 4, height: 32, borderRadius: 9999, background: C.coral, boxShadow: '0 0 18px rgba(243,107,89,0.22)' }} />
          <div style={{ fontFamily: TIGHT, fontSize: 52, fontWeight: 600, letterSpacing: -1.8, whiteSpace: 'nowrap', lineHeight: 1.1 }}>A claim too absolute</div>
        </div>

        {/* 4. One inspection mechanism; all internal coordinates are stable. */}
