  const cues = props.wordCues || [];
  const normalize = (value: string) => value.toLowerCase().replace(/[^a-z]/g, "");
  const cueAt = (index: number, word: string, fallback: number) => {
    const found = cues.find((cue) => cue.wordIndex === index || cue.index === index || String(cue.id) === `W${index}` || String(cue.id) === String(index)) || cues.find((cue) => normalize(cue.word || cue.text || "") === normalize(word));
    return found && typeof found.startFrame === "number" ? found.startFrame : fallback;
  };
  const at = {
    blockchain: cueAt(373, "Blockchain", 0),
    ledger: cueAt(377, "ledger", 117),
    extremely: cueAt(378, "extremely", 169),
    difficult: cueAt(379, "difficult", 206),
    alter: cueAt(381, "alter", 238),
    but: cueAt(382, "but", 298),
    election: cueAt(384, "election", 312),
    system: cueAt(385, "system", 334),
    has: cueAt(386, "has", 380),
    many: cueAt(387, "many", 397),
    other: cueAt(388, "other", 415),
    components: cueAt(389, "components", 426)
  };
  const ramp = (start: number, end: number, from = 0, to = 1) => interpolate(frame, [start, Math.max(start + 1, end)], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });
  const settle = (start: number) => spring({ frame: Math.max(0, frame - start), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const f = Math.min(frame, durationInFrames - 1);
  const zoom = interpolate(f, [0, at.but, at.but + 13, at.election + 52, at.has, at.other + 13, Math.max(at.other + 14, durationInFrames - 1)], [1.24, 1.24, 1.12, 1.06, 1.06, 1, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });
  const panX = interpolate(f, [0, at.election, at.election + 52, at.has, at.other + 13, Math.max(at.other + 14, durationInFrames - 1)], [0, 0, 40, 40, 0, 8], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });
