import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type RecordedToken = { id?: string; recordId?: string; payload?: string; payloadLabel?: string };
type ShotProps = {
  wordCues?: WordCue[];
  recordToken?: RecordedToken;
  previousRecordToken?: RecordedToken;
  recordId?: string;
  recordedPayload?: string;
};

const C = { ink: "#17233B", slate: "#64748B", blue: "#315EFF", electric: "#0066FF", emerald: "#00A77B", coral: "#F36B59", amber: "#E8AD36" };
const FONT = "'Inter', 'Arial', sans-serif";
const TIGHT = "'Inter Tight', 'Inter', 'Arial', sans-serif";
const MONO = "'IBM Plex Mono', 'SFMono-Regular', monospace";
const SMOOTH = Easing.bezier(0.4, 0, 0.2, 1);
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

const Check = ({ size = 24, color = C.emerald }: { size?: number; color?: string }) => (
  <svg width={size} height={size} viewBox="0 0 28 28" fill="none" aria-hidden="true">
    <path d="M5 14.5L11 20L23 7.5" stroke={color} strokeWidth="3.1" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);
  const cueAt = (index: number, fallback: number) => {
    const indexed = cues.find((cue) => cue.wordIndex === index || cue.index === index);
    const local = cues.length === 25 ? cues[index - 437] : undefined;
    return indexed?.startFrame ?? local?.startFrame ?? fallback;
  };
  const at = {
    distinction: cueAt(440, 34), blockchain: cueAt(441, 106), can: cueAt(442, 135),
    protect: cueAt(443, 144), integrity: cueAt(445, 173), after: cueAt(448, 273),
    recorded: cueAt(450, 303), it: cueAt(451, 374), cannot: cueAt(452, 380),
    guarantee: cueAt(453, 399), information: cueAt(456, 443), entering: cueAt(457, 483),
    system: cueAt(459, 518), correct: cueAt(461, 549)
  };
  const tween = (a: number, b: number, from = 0, to = 1) => interpolate(f, [a, Math.max(a + 1, b)], [from, to], { ...clamp, easing: SMOOTH });
  const appear = (start: number) => f < start ? 0 : spring({ frame: f - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const unit = (value: number) => Math.max(0, Math.min(1, value));

  const pose = (a: number, b: number, c: number, d: number, e: number) => interpolate(
    f,
    [0, 64, at.blockchain, at.integrity + 40, at.recorded + 25, at.it, at.information + 4, at.entering, at.correct + 16, Math.max(at.correct + 17, 590)],
    [a, b, b, c, c, c, d, d, e, e],
    { ...clamp, easing: SMOOTH }
  );
  const zoom = pose(1.04, 1.025, 1.08, 1.03, 1);
  const panX = pose(-24, -10, -42, 18, 0);
  const panY = pose(-10, -5, -15, -10, 0);
  const layoutScale = Math.min(width / 1920, height / 1080);
  const diagramOpacity = tween(0, at.distinction + 24, 0.80, 1);
  const canReveal = appear(at.can);
  const checkReveal = appear(at.integrity);
  const scopeReveal = tween(at.after, at.recorded + 25);
  const cannotReveal = appear(at.cannot);
  const focusProgress = tween(at.it, at.information + 4);
  const focusX = interpolate(focusProgress, [0, 1], [1147, 347]);
