        <AbsoluteFill style={{ background: "radial-gradient(ellipse 53% 66% at " + (72 + tween(0, 565, 0, 2)) + "% 38%, rgba(255,255,255,0.98) 0%, rgba(255,255,255,0.52) 39%, rgba(219,232,255,0.16) 69%, transparent 87%)" }} />
