import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  index?: number;
  wordIndex?: number;
  globalIndex?: number;
  id?: number | string;
  startFrame?: number;
  start?: number;
  word?: string;
  text?: string;
};
type ShotProps = {
  wordCues?: WordCue[];
  recordId?: string;
  inheritedRecordId?: string;
};
type Requirement = {
  key: string;
  x: number;
  y: number;
  width: number;
  lines: string[];
  at: number;
};

const C = {
  porcelain: "#F3F5F8",
  ink: "#17233B",
  slate: "#64748B",
  blue: "#315EFF",
  coral: "#F36B59",
  white: "#F8FAFC",
};
const FONT = '"Inter", "Arial", sans-serif';
const TIGHT = '"Inter Tight", "Inter", "Arial", sans-serif';
const MONO = '"IBM Plex Mono", "SFMono-Regular", monospace';
const ease = Easing.inOut(Easing.cubic);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);
  const normalized = (s: string) => s.toLowerCase().replace(/[^a-z0-9-]/g, "");
  const cueAt = (index: number, word: string, fallback: number) => {
    const found = cues.find((c) => c.wordIndex === index || c.index === index || c.globalIndex === index || c.id === index || c.id === `W${index}`)
      || cues.find((c) => normalized(c.word || c.text || "") === normalized(word));
    const value = found?.startFrame ?? found?.start;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const countingAt = cueAt(517, "accurate", 57);
  const voterAt = cueAt(519, "voter", 121);
  const ballotAt = cueAt(521, "ballot", 215);
  const resistanceAt = cueAt(523, "resistance", 283);
  const accessibilityAt = cueAt(526, "accessibility", 381);
  const auditabilityAt = cueAt(527, "auditability", 456);
  const securityAt = cueAt(529, "security", 534);
  const ballotPanAt = Math.max(53, ballotAt - 23);
  const rightPanAt = Math.max(ballotAt + 1, accessibilityAt - 16);
  const dipAt = cueAt(527, "auditability", 456) + 48;
  const dipEnd = cueAt(530, "against", 570);
  const pullAt = cueAt(531, "large-scale", 591) + 41;
  const pullEnd = cueAt(532, "attacks", 629) + 29;

  const move = (a: number, b: number, start: number, end: number) => interpolate(f, [a, Math.max(a + 1, b)], [start, end], { ...clamp, easing: ease });
  let zoom = move(0, 52, 1, 1.10);
  let panX = move(0, 52, 0, 70);
  let panY = move(0, 52, 0, 8);
  if (f >= ballotPanAt) panX = move(ballotPanAt, ballotAt, 70, 0);
  if (f >= rightPanAt) panX = move(rightPanAt, accessibilityAt, 0, -70);
  if (f >= dipAt) {
    zoom = move(dipAt, dipEnd, 1.10, 1.06);
    panX = move(dipAt, dipEnd, -70, 0);
    panY = move(dipAt, dipEnd, 8, -35);
  }
  if (f >= pullAt) {
    zoom = move(pullAt, pullEnd, 1.06, 1);
    panX = 0;
    panY = move(pullAt, pullEnd, -35, 0);
  }
  if (f >= pullEnd) {
    zoom = move(pullEnd, Math.max(pullEnd + 1, durationInFrames - 1), 1, 1.015);
    panX = 0;
    panY = 0;
  }

  const dock = (delay: number) => spring({ frame: Math.max(0, f - delay), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const reveal = (at: number) => interpolate(f, [at, at + 11], [0, 1], clamp);
  const intro = dock(2);
  const stageX = 115 - 16 * (1 - intro);
  const stageY = 170 - 6 * (1 - intro);
  const stageWidth = 1690 + 32 * (1 - intro);
  const stageHeight = 850 + 10 * (1 - intro);
  const groupDelays = [9, 14, 19, 24];
  const groupTravel = groupDelays.map((delay) => 15 * (1 - dock(delay)));
  const groupOpacity = groupDelays.map((delay) => interpolate(f, [delay, delay + 16], [0, 1], clamp));

  const requirements: Requirement[] = [
    { key: "counting", x: 304, y: 329, width: 382, lines: ["ACCURATE", "COUNTING"], at: countingAt },
    { key: "authentication", x: 304, y: 497, width: 382, lines: ["VOTER", "AUTHENTICATION"], at: voterAt },
    { key: "secrecy", x: 769, y: 329, width: 382, lines: ["BALLOT", "SECRECY"], at: ballotAt },
    { key: "coercion", x: 769, y: 497, width: 382, lines: ["RESISTANCE", "TO COERCION"], at: resistanceAt },
    { key: "accessibility", x: 1234, y: 329, width: 382, lines: ["ACCESSIBILITY"], at: accessibilityAt },
    { key: "auditability", x: 1234, y: 497, width: 382, lines: ["AUDITABILITY"], at: auditabilityAt },
    { key: "security", x: 280, y: 709, width: 1360, lines: ["SECURITY AGAINST", "LARGE-SCALE ATTACKS"], at: securityAt },
  ];
  const recordId = props.inheritedRecordId || props.recordId || "R-01";
  const railTravel = 7 * (1 - dock(5));
  const fieldSurface = "linear-gradient(155deg, rgba(48,67,100,0.98) 0%, rgba(27,43,69,0.99) 56%, rgba(31,49,79,0.99) 100%)";
  const fieldShadow = "inset 0 1px 0 rgba(255,255,255,0.09), 0 10px 25px rgba(0,102,255,0.15), 0 4px 12px rgba(7,10,18,0.20)";

  const renderField = (r: Requirement, localX: number, localY: number) => {
    const visible = reveal(r.at);
    const textSpring = dock(r.at);
    return (
      <div key={r.key} style={{ position: "absolute", left: localX, top: localY, width: r.width, height: 136, borderRadius: 22, boxSizing: "border-box", overflow: "hidden", background: fieldSurface, border: "1px solid rgba(222,235,255,0.23)", boxShadow: fieldShadow }}>
        {f >= r.at && (
          <div style={{ position: "absolute", inset: 0, borderRadius: 22, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", padding: "0 15px", boxSizing: "border-box", opacity: visible, transform: `translateY(${10 * (1 - textSpring)}px)`, color: C.white, fontFamily: FONT, fontWeight: 500, fontSize: 26, lineHeight: "34px", letterSpacing: "0.35px", textAlign: "center", textShadow: "0 2px 10px rgba(0,0,0,0.14)" }}>
            {r.lines.map((line) => <div key={line} style={{ whiteSpace: "nowrap" }}>{line}</div>)}
          </div>
        )}
      </div>
    );
  };

  // The rig is exactly 1920 x 1080. Pre/post translation moves its native
  // center from (960,540) to (960,575): p' = P + zoom*(p-P) + pan.
  // Every field, tab and the record rail is inside this single transform.
  return (
    <AbsoluteFill style={{ background: C.porcelain, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: (width - 1920 * Math.min(width / 1920, height / 1080)) / 2, top: (height - 1080 * Math.min(width / 1920, height / 1080)) / 2, width: 1920, height: 1080, transformOrigin: "0 0", transform: `scale(${Math.min(width / 1920, height / 1080)})`, fontFamily: FONT, color: C.ink, isolation: "isolate" }}>
