import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  index?: number;
  wordIndex?: number;
  id?: string | number;
  word?: string;
  text?: string;
  startFrame?: number;
  endFrame?: number;
};
type ShotProps = {
  wordCues?: WordCue[];
  recordId?: string;
};

const BLUE = '#315EFF';
const INK = '#17233B';
const CORAL = '#F36B59';
const AMBER = '#E8AD36';
const FONT = 'Inter, Arial, sans-serif';
const TIGHT = 'Inter Tight, Inter, Arial, sans-serif';
const MONO = 'IBM Plex Mono, Consolas, monospace';
const EASE = Easing.inOut(Easing.cubic);
const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

const REQUIREMENTS = [
  { id: '01', x: 210, y: 270, w: 450, h: 100, label: 'ACCURATE COUNTING', lines: ['ACCURATE COUNTING'], port: [722, 440], path: 'M435 370 C435 409 722 391 722 440' },
  { id: '02', x: 700, y: 270, w: 450, h: 100, label: 'VOTER AUTHENTICATION', lines: ['VOTER AUTHENTICATION'], port: [944, 440], path: 'M925 370 C925 402 944 406 944 440' },
  { id: '03', x: 1190, y: 270, w: 450, h: 100, label: 'BALLOT SECRECY', lines: ['BALLOT SECRECY'], port: [1170, 440], path: 'M1415 370 C1415 410 1170 393 1170 440' },
  { id: '04', x: 210, y: 440, w: 300, h: 120, label: 'RESISTANCE TO COERCION', lines: ['RESISTANCE', 'TO COERCION'], port: [640, 492], path: 'M510 500 C564 500 588 492 640 492' },
  { id: '05', x: 1340, y: 440, w: 300, h: 120, label: 'ACCESSIBILITY', lines: ['ACCESSIBILITY'], port: [1280, 492], path: 'M1340 500 C1315 500 1310 492 1280 492' },
  { id: '06', x: 1340, y: 590, w: 300, h: 120, label: 'AUDITABILITY', lines: ['AUDITABILITY'], port: [1280, 646], path: 'M1340 650 C1315 650 1310 646 1280 646' },
  { id: '07', x: 210, y: 750, w: 590, h: 110, label: 'SECURITY AGAINST LARGE-SCALE ATTACKS', lines: ['SECURITY AGAINST', 'LARGE-SCALE ATTACKS'], port: [640, 646], path: 'M505 750 C505 697 566 646 640 646' },
];

function pointOnFeed(t: number) {
  const u = 1 - t;
  return {
    x: u * u * u * 1190 + 3 * u * u * t * 1190 + 3 * u * t * t * 1070 + t * t * t * 1070,
    y: u * u * u * 810 + 3 * u * u * t * 745 + 3 * u * t * t * 745 + t * t * t * 675,
  };
}

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number) => {
    const hit = cues.find((item, localIndex) => {
      const suppliedId = item.wordIndex ?? item.index ?? item.id;
      if (suppliedId !== undefined) return Number(String(suppliedId).replace(/^W/i, '')) === index;
      return cues.length === 14 && localIndex === index - 533;
    });
    return typeof hit?.startFrame === 'number' ? hit.startFrame : fallback;
  };
  const endCue = (index: number, fallback: number) => {
    const hit = cues.find((item, localIndex) => {
      const suppliedId = item.wordIndex ?? item.index ?? item.id;
      if (suppliedId !== undefined) return Number(String(suppliedId).replace(/^W/i, '')) === index;
      return cues.length === 14 && localIndex === index - 533;
    });
    return typeof hit?.endFrame === 'number' ? hit.endFrame : fallback;
  };
  const blockchainAt = cue(533, 0);
  const canAt = cue(534, 62);
  const helpAt = cue(535, 82);
  const withAt = cue(536, 108);
  const someAt = cue(537, 117);
  const piecesAt = cue(538, 129);
  const butAt = cue(539, 202);
  const itAt = cue(540, 216);
  const doesntAt = cue(541, 226);
  const magicallyAt = cue(542, 251);
  const solveAt = cue(543, 282);
  const theAt = cue(544, 314);
  const entireAt = cue(545, 326);
  const puzzleAt = cue(546, 343);
  const piecesEnd = Math.max(canAt + 1, endCue(538, 156));
  const magicallyEnd = Math.max(butAt + 1, endCue(542, 286));
  const puzzleEnd = Math.max(theAt + 1, Math.min(durationInFrames - 1, endCue(546, 370)));
  const phase = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { ...CLAMP, easing: EASE });
  const snap = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });

  const tracking = phase(canAt, piecesEnd);
  const upperTracking = phase(butAt, magicallyEnd);
  const pullback = phase(theAt, puzzleEnd);
  const requestedZoom = (1.15 + 0.03 * tracking - 0.03 * upperTracking) * (1 - pullback) + pullback;
  const requestedX = (-35 - 15 * tracking + 30 * upperTracking) * (1 - pullback);
  const requestedY = (-15 - 5 * tracking - 5 * upperTracking) * (1 - pullback);

  // Camera mapping is pivot + (point - pivot + offset) * zoom.
  // Include the editorial envelope as well as all critical nodes in the bounds.
  const pivotX = 960;
  const pivotY = 590;
  const bounds = { left: 184, right: 1668, top: 236, bottom: 956 };
  const safe = { left: 116, right: 1804, top: 201, bottom: 999 };
  const zoom = Math.max(1, Math.min(requestedZoom, 1.18, (safe.right - safe.left) / (bounds.right - bounds.left), (safe.bottom - safe.top) / (bounds.bottom - bounds.top)));
  const minX = (safe.left - pivotX) / zoom - (bounds.left - pivotX);
  const maxX = (safe.right - pivotX) / zoom - (bounds.right - pivotX);
  const minY = (safe.top - pivotY) / zoom - (bounds.top - pivotY);
  const maxY = (safe.bottom - pivotY) / zoom - (bounds.bottom - pivotY);
  const panX = Math.max(minX, Math.min(maxX, requestedX));
  const panY = Math.max(minY, Math.min(maxY, requestedY));
  // CameraRig is centered on the 1920x1080 plane. This correction moves its pivot
  // to (960,590) while preserving the requested pre-zoom offset mapping.
  const rigX = panX * zoom;
  const rigY = panY * zoom + (1 - zoom) * (pivotY - 540);

  const recordIntro = Math.min(1, Math.max(0, snap(blockchainAt + 4)));
  const localHelp = phase(helpAt, helpAt + 14);
  const scopeReveal = phase(someAt, piecesAt + 15);
  const boundaryReveal = phase(itAt, doesntAt + 14);
  const limitationReveal = phase(doesntAt, solveAt + 14);
  const assemblyReveal = phase(theAt, puzzleEnd);
  const wholeLabelReveal = phase(entireAt, puzzleAt + 16);
  const pulseProgress = phase(canAt, piecesEnd);
  const pulsePoint = pointOnFeed(pulseProgress);
  const pulseOpacity = frame < canAt || frame >= piecesEnd ? 0 : Math.min(1, (frame - canAt) / 7, (piecesEnd - frame) / 7);
  const arrival = phase(piecesEnd, piecesEnd + 36);
  const arrivalOpacity = frame >= piecesEnd && frame <= piecesEnd + 36 ? 1 - arrival : 0;
  const scopeSweep = phase(butAt, magicallyEnd);
  const scanOpacity = frame >= butAt && frame < solveAt + 24 ? Math.sin(Math.PI * phase(butAt, solveAt + 24)) : 0;
  const tokenHalo = 0.2 + 0.11 * Math.sin(frame / 28);
  const envelopeMorph = phase(blockchainAt, withAt);
  const recordId = props.recordId || 'R-027';
  const blueShadow = '0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(23,35,59,0.08)';
  const neutralShadow = '0 20px 60px rgba(0,102,255,0.10), 0 8px 24px rgba(23,35,59,0.045)';

  return (
    <AbsoluteFill style={{ background: '#F3F5F8', overflow: 'hidden', fontFamily: FONT }}>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920) / 2, top: (height - 1080) / 2, color: INK, overflow: 'hidden', borderRadius: 24 }}>
        <AbsoluteFill style={{ background: 'linear-gradient(155deg, #FAFCFF 0%, #F3F5F8 34%, #E4ECF8 72%, #F6F8FC 100%)' }} />
        <AbsoluteFill style={{ opacity: 0.44 }}>
          <mg.GridBackground mode="light" gridSize={48} />
        </AbsoluteFill>
        <AbsoluteFill style={{ background: 'radial-gradient(48% 58% at 64% 52%, rgba(49,94,255,0.13) 0%, rgba(49,94,255,0.045) 42%, transparent 76%), radial-gradient(32% 46% at 19% 78%, rgba(232,173,54,0.085) 0%, transparent 76%)', transform: 'translateX(' + 8 * Math.sin(frame / 125) + 'px)' }} />

        <div style={{ position: 'absolute', left: 116, top: 82, fontFamily: TIGHT, fontSize: 52, fontWeight: 600, lineHeight: 1, letterSpacing: -1.8, whiteSpace: 'nowrap', zIndex: 5 }}>
          A useful layer. Not the whole system.
        </div>
        <div style={{ position: 'absolute', left: 116, top: 140, display: 'flex', alignItems: 'center', gap: 16, fontSize: 22, fontWeight: 500, lineHeight: '28px', letterSpacing: 2.1, zIndex: 5 }}>
          <span style={{ width: 10, height: 10, borderRadius: 9999, background: BLUE, boxShadow: '0 0 18px rgba(49,94,255,0.25)' }} />
          <span>DOCUMENTARY DOSSIER</span>
          <span style={{ color: '#7C8BA3' }}>/</span>
          <span style={{ color: '#53647F' }}>ELECTION REQUIREMENTS</span>
        </div>
        <div style={{ position: 'absolute', right: 116, top: 91, width: 140, height: 45, borderRadius: 9999, background: 'rgba(255,255,255,0.75)', border: '1px solid rgba(49,94,255,0.14)', boxShadow: neutralShadow, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, fontFamily: MONO, fontSize: 17, color: '#526580', zIndex: 5 }}>
          <span style={{ width: 7, height: 7, borderRadius: 9999, background: AMBER }} />
          <span>27 / SCOPE</span>
        </div>

        <div style={{ position: 'absolute', left: 115, top: 190, width: 1690, height: 810, borderRadius: 24, background: 'rgba(255,255,255,0.76)', backdropFilter: 'blur(14px)', border: '1px solid rgba(49,94,255,0.17)', boxShadow: '0 20px 60px rgba(0,102,255,0.12), 0 8px 24px rgba(23,35,59,0.06)', overflow: 'hidden', isolation: 'isolate' }}>
          <div style={{ position: 'absolute', inset: 0, borderRadius: 24, background: 'radial-gradient(58% 65% at 62% 49%, rgba(49,94,255,0.085), transparent 74%), linear-gradient(115deg, rgba(255,255,255,0.65), transparent 55%)' }} />
          <div style={{ position: 'absolute', left: -115, top: -190, width: 1920, height: 1080 }}>
            <mg.CameraRig zoom={zoom} x={rigX} y={rigY}>
              <AbsoluteFill>
                <svg width={1920} height={1080} viewBox="0 0 1920 1080" style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
                  <defs>
                    <filter id="mgGlow" x="-90%" y="-90%" width="280%" height="280%">
                      <feGaussianBlur stdDeviation="5" result="blur" />
                      <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
                    </filter>
                    <filter id="mgSoft" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation="10" />
                    </filter>
                  </defs>

                  <rect x={190} y={242} width={1472} height={704} rx={24} ry={24} fill="rgba(246,249,255,0.28)" stroke="rgba(100,116,139,0.25)" strokeWidth={1.5} opacity={0.72 + envelopeMorph * 0.28} />
                  <path d="M214 242 C201 242 190 253 190 266 L190 922 C190 935 201 946 214 946" fill="none" stroke="#91A2BC" strokeWidth={2} strokeLinecap="round" opacity={0.7 - 0.25 * envelopeMorph} />
                  <path d="M1638 242 C1651 242 1662 253 1662 266 L1662 922 C1662 935 1651 946 1638 946" fill="none" stroke="#91A2BC" strokeWidth={2} strokeLinecap="round" opacity={0.7 - 0.25 * envelopeMorph} />

                  {REQUIREMENTS.map((item) => (
                    <g key={'conduit-' + item.id}>
                      <path d={item.path} fill="none" stroke="rgba(49,94,255,0.065)" strokeWidth={11} strokeLinecap="round" />
                      <path d={item.path} fill="none" stroke="#9AA9BE" strokeWidth={2.2} strokeLinecap="round" />
                    </g>
                  ))}

                  <path d="M1190 810 C1190 745 1070 745 1070 675" fill="none" stroke="rgba(49,94,255,0.08)" strokeWidth={12} strokeLinecap="round" />
                  <path d="M1190 810 C1190 745 1070 745 1070 675" fill="none" stroke="rgba(49,94,255,0.38)" strokeWidth={2.6} strokeLinecap="round" />
                  <path d="M1190 810 C1190 745 1070 745 1070 675" pathLength={1} fill="none" stroke={BLUE} strokeWidth={6} strokeLinecap="round" strokeDasharray="0.055 1" strokeDashoffset={-pulseProgress} opacity={pulseOpacity} filter="url(#mgGlow)" />
                  <circle cx={pulsePoint.x} cy={pulsePoint.y} r={6} fill={BLUE} opacity={pulseOpacity} filter="url(#mgGlow)" />
                </svg>

                {REQUIREMENTS.map((item, index) => {
                  const settle = phase(blockchainAt + index * 5, withAt + index * 2);
                  return (
                    <div key={item.id} style={{ position: 'absolute', left: item.x, top: item.y, width: item.w, height: item.h, borderRadius: 24, boxSizing: 'border-box', background: 'linear-gradient(150deg, rgba(255,255,255,0.98), rgba(246,249,253,0.98))', border: '1px solid rgba(118,139,170,0.30)', boxShadow: neutralShadow, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
