const clamp = (n: number) => Math.max(0, Math.min(1, n));

const Rail = ({ x, y, w, h, color, progress = 1, opacity = 1, reverse = false, glow = false }: { x: number; y: number; w: number; h: number; color: string; progress?: number; opacity?: number; reverse?: boolean; glow?: boolean }) => {
  const horizontal = w >= h;
  return (
    <div style={{ position: 'absolute', left: x, top: y, width: w, height: h, borderRadius: 9999, overflow: 'hidden', opacity }}>
      <div style={{ position: 'absolute', left: reverse && horizontal ? undefined : 0, right: reverse && horizontal ? 0 : undefined, top: reverse && !horizontal ? undefined : 0, bottom: reverse && !horizontal ? 0 : undefined, width: horizontal ? `${clamp(progress) * 100}%` : '100%', height: horizontal ? '100%' : `${clamp(progress) * 100}%`, borderRadius: 9999, background: color, boxShadow: glow ? `0 0 14px ${color}` : undefined }} />
    </div>
  );
};

