  const fade = (start: number, length = 16) => interpolate(frame, [start, start + length], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const snap = (start: number) => spring({ frame: Math.max(0, frame - start), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
