type WordCue = {
  wordIndex?: number;
  index?: number;
  startFrame?: number;
  word?: string;
  text?: string;
};

type ShotProps = {
  wordCues?: WordCue[];
  recordId?: string;
  inheritedRecordId?: string;
  recordToken?: { id?: string };
};

